insert into hygieia.skincare_product_types (id, slug, name_el, name_en, description_el, description_en, category, key_ingredients, avoid_with, regions, audiences, skin_types, concerns, time, price_band_eur, notes_el, notes_en) values
  ('e9add044-8940-9e16-42dc-829b1559aee5'::uuid, 'base-coat-breathable', 'Προστατευτική βάση (base coat) που «αναπνέει»', 'Breathable base coat', 'Διάφανη βάση που μπαίνει πριν το χρώμα: προστατεύει την πλάκα από χρωστικές, κάνει το βερνίκι να κρατά και μειώνει το κιτρίνισμα. Οι εκδοχές «water-permeable» αφήνουν λίγο νερό και οξυγόνο να περνούν.', 'A clear base applied before colour: it shields the plate from pigments, helps polish last and reduces yellowing. “Water-permeable” versions let a little water and oxygen through.', 'base_coat', array['nitrocellulose','adipic acid copolymer','panthenol']::text[], '{}'::text[], array['global','us']::text[], array['women','all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'low', 'Οι όροι «5-free», «10-free» κ.λπ. δηλώνουν ποια αμφιλεγόμενα συστατικά λείπουν (τολουόλιο, φθαλικά, φορμαλδεΰδη)· είναι εμπορικές ετικέτες, όχι επίσημος κανόνας.', 'Labels such as “5-free” or “10-free” list which controversial ingredients are left out (toluene, phthalates, formaldehyde); they are marketing terms, not an official standard.'),
  ('7c3a4d53-ae49-61a8-8317-d1bc15a79f0c'::uuid, 'beard-balm', 'Βάλσαμο γενειάδας', 'Beard balm', 'Έλαια σε βάση βουτύρου και κεριού που ενυδατώνουν και ταυτόχρονα δίνουν ελαφρύ κράτημα και σχήμα στη γενειάδα. Για μεσαίες και μεγάλες γενειάδες.', 'Oils in a butter-and-wax base that moisturise while giving the beard light hold and shape. For medium and long beards.', 'beard', array['shea butter','beeswax','jojoba oil','argan oil']::text[], '{}'::text[], array['global','us']::text[], array['men']::text[], array['all']::text[], array['beard']::text[], 'am', 'mid', 'Ζέστανε μια μικρή ποσότητα στις παλάμες μέχρι να λιώσει πριν την περάσεις.', 'Warm a small amount between your palms until it melts before working it through.'),
  ('b0f7cfe2-a9b0-bf14-49dc-bfaefc104f1c'::uuid, 'beard-oil', 'Έλαιο γενειάδας', 'Beard oil', 'Ελαφριά έλαια που μαλακώνουν την τρίχα και ενυδατώνουν το δέρμα κάτω από τη γενειάδα, μειώνοντας φαγούρα και «πιτυρίδα γενειάδας». Λίγες σταγόνες σε στεγνή ή ελαφρώς νωπή γενειάδα.', 'Light oils that soften the hair and moisturise the skin under the beard, cutting itch and “beardruff”. A few drops on a dry or slightly damp beard.', 'beard', array['jojoba oil','argan oil','grapeseed oil','vitamin e']::text[], '{}'::text[], array['global','us']::text[], array['men']::text[], array['all']::text[], array['beard','hydration']::text[], 'both', 'mid', 'Αν η φαγούρα επιμένει ή έχει ξεφλούδισμα και κοκκινίλα, μπορεί να είναι σμηγματορροϊκή δερματίτιδα — ρώτα δερματολόγο.', 'If the itch persists with flaking and redness, it may be seborrhoeic dermatitis — ask a dermatologist.'),
  ('f09d44f7-1394-9127-17b3-01aa01c978af'::uuid, 'beard-wash', 'Σαμπουάν γενειάδας', 'Beard wash', 'Ήπιο καθαριστικό για την τρίχα και το δέρμα της γενειάδας, πιο μαλακό από σαμπουάν μαλλιών και πιο αποτελεσματικό από καθαριστικό προσώπου στην τρίχα. 2–3 φορές την εβδομάδα.', 'A mild cleanser for beard hair and the skin beneath, softer than hair shampoo and better than a face cleanser at cleaning hair. Two or three times a week.', 'beard', array['coco-glucoside','glycerin','aloe vera','tea tree']::text[], '{}'::text[], array['global']::text[], array['men']::text[], array['all']::text[], array['beard']::text[], 'pm', 'low', 'Καθημερινό πλύσιμο με σαμπουάν μαλλιών ξηραίνει τη γενειάδα και το δέρμα από κάτω.', 'Daily washing with hair shampoo dries the beard and the skin under it.'),
  ('1b6090b7-02f5-000a-dae8-db0a64e65969'::uuid, 'cleanser-cream-milk', 'Κρεμώδες καθαριστικό / γαλάκτωμα', 'Cream or milk cleanser', 'Καθαριστικό χαμηλού αφρισμού με μαλακτικά λιπίδια, για ξηρή και ευαίσθητη επιδερμίδα. Καθαρίζει χωρίς να αφαιρεί τα φυσικά λιπίδια του φραγμού.', 'A low-foam cleanser with emollient lipids for dry and sensitive skin. It cleanses without stripping the barrier’s own lipids.', 'cleanser', array['glycerin','ceramides','squalane','shea butter']::text[], '{}'::text[], array['eu','global']::text[], array['all']::text[], array['dry','sensitive','normal']::text[], array['hydration','redness','general']::text[], 'both', 'low', 'Στην ΕΕ τα καλλυντικά υπόκεινται στον Κανονισμό 1223/2009· τα συστατικά αναγράφονται με INCI ονομασίες και ο όρος «δερματολογικά ελεγμένο» δεν σημαίνει έγκριση.', 'In the EU cosmetics fall under Regulation 1223/2009; ingredients are listed by INCI name and “dermatologically tested” is not an approval.'),
  ('f5a77228-4213-9757-2377-225dcf06981d'::uuid, 'cleanser-gel-foaming', 'Αφρίζον καθαριστικό gel', 'Foaming gel cleanser', 'Ελαφρύ καθαριστικό με ήπιους επιφανειοδραστικούς παράγοντες που αφαιρεί σμήγμα, ιδρώτα και αντηλιακό χωρίς να αφήνει φιλμ. Η βασική επιλογή για λιπαρή και μικτή επιδερμίδα, πρωί και βράδυ.', 'A light cleanser with mild surfactants that lifts sebum, sweat and sunscreen without leaving a film. The default choice for oily and combination skin, morning and evening.', 'cleanser', array['glycerin','cocamidopropyl betaine','niacinamide','zinc pca']::text[], '{}'::text[], array['global']::text[], array['all']::text[], array['oily','combination','normal']::text[], array['acne','pores','general']::text[], 'both', 'low', 'Αν η επιδερμίδα «τραβάει» μετά το πλύσιμο, το καθαριστικό είναι πολύ δυνατό για σένα· δοκίμασε κρεμώδες.', 'If your skin feels tight after washing, the cleanser is too strong for you; switch to a cream one.'),
  ('c26f1ae5-fa22-92e2-9f73-cf01ffc60f9c'::uuid, 'cleanser-micellar-water', 'Μικυλλιακό νερό', 'Micellar water', 'Γαλλικής καταγωγής καθαριστικό χωρίς ξέβγαλμα, με μικύλλια που «πιάνουν» ρύπους και ελαφρύ μακιγιάζ. Βολικό για γρήγορο καθαρισμό ή ως πρώτο βήμα πριν το πλύσιμο.', 'A French-born rinse-free cleanser whose micelles pick up dirt and light make-up. Handy for a quick cleanse or as the first step before washing.', 'cleanser', array['poloxamer','glycerin','hexylene glycol']::text[], '{}'::text[], array['eu']::text[], array['all']::text[], array['all']::text[], array['general']::text[], 'pm', 'low', 'Παρά την ετικέτα «χωρίς ξέβγαλμα», το ξέβγαλμα μειώνει τον ερεθισμό σε ευαίσθητες επιδερμίδες.', 'Despite the “no-rinse” label, rinsing afterwards reduces irritation on sensitive skin.'),
  ('38db16c7-b551-1741-af53-cddc8cc489b9'::uuid, 'cleanser-oil-balm', 'Έλαιο ή βάλσαμο καθαρισμού', 'Cleansing oil or balm', 'Το πρώτο βήμα του «διπλού καθαρισμού» κορεατικού τύπου: διαλύει αντηλιακό, μακιγιάζ και σμήγμα και ξεπλένεται με νερό χάρη σε γαλακτωματοποιητές. Ακολουθεί ένα καθαριστικό με βάση το νερό.', 'Step one of the Korean-style “double cleanse”: it dissolves sunscreen, make-up and sebum and rinses off with water thanks to emulsifiers. A water-based cleanser follows.', 'cleanser', array['mineral oil','sunflower seed oil','polysorbate','squalane']::text[], '{}'::text[], array['kr','jp']::text[], array['all']::text[], array['all']::text[], array['general','pores']::text[], 'pm', 'mid', 'Μόνο βράδυ, και μόνο αν φοράς αντηλιακό ή μακιγιάζ· το πρωί αρκεί ένα απλό καθαριστικό.', 'Evening only, and only when you wear sunscreen or make-up; in the morning a single cleanser is enough.'),
  ('87199db0-7470-5635-c10e-51d0803ecfd6'::uuid, 'cuticle-oil-jojoba', 'Λάδι επωνυχίων', 'Cuticle oil', 'Ελαφριά έλαια (jojoba, αμυγδάλου, βιταμίνη Ε) που μαλακώνουν τα επωνύχια και ενυδατώνουν την πλάκα του νυχιού, ώστε να λυγίζει αντί να σπάει. Μία-δύο φορές τη μέρα, με μασάζ στη βάση του νυχιού.', 'Light oils (jojoba, almond, vitamin E) that soften the cuticles and hydrate the nail plate so it bends instead of snapping. Once or twice a day, massaged into the nail base.', 'cuticle_oil', array['jojoba oil','sweet almond oil','vitamin e','squalane']::text[], '{}'::text[], array['global']::text[], array['all']::text[], array['all']::text[], array['nails','hands']::text[], 'both', 'low', 'Το πιο αποτελεσματικό βήμα για εύθραυστα νύχια είναι η σταθερή ενυδάτωση, όχι τα «ενισχυτικά» με φορμαλδεΰδη.', 'The most effective step for brittle nails is consistent moisture, not formaldehyde “hardeners”.'),
  ('243f25f7-40ee-d8a8-f03e-7813f89eb67a'::uuid, 'essence-first-treatment', 'First treatment essence (ζυμωμένα εκχυλίσματα)', 'First treatment essence (fermented)', 'Υδατικό προϊόν με ζυμωμένα εκχυλίσματα (μαγιά, ρύζι) που εφαρμόζεται πρώτο μετά τον καθαρισμό στην κορεατική και ιαπωνική ρουτίνα. Στόχος η λάμψη και η ομοιόμορφη υφή.', 'A watery product with fermented extracts (yeast, rice) applied first after cleansing in Korean and Japanese routines. The aim is glow and an even texture.', 'essence', array['galactomyces ferment filtrate','rice ferment','niacinamide']::text[], '{}'::text[], array['kr','jp']::text[], array['all']::text[], array['normal','dry','combination']::text[], array['texture','pigmentation','hydration']::text[], 'both', 'high', 'Τα ζυμωμένα εκχυλίσματα ενοχλούν κάποιες επιδερμίδες με τάση για ακμή από μύκητες (fungal acne)· κάνε patch test.', 'Fermented extracts bother some skins prone to fungal acne; patch test first.'),
  ('4fd92820-66fd-679b-bc03-de5bbb068ba8'::uuid, 'essence-hydrating', 'Ενυδατική essence', 'Hydrating essence', 'Κορεατικό ενδιάμεσο βήμα, πιο «πυκνό» από τόνερ και πιο αραιό από ορό. Προσθέτει νερό και συστατικά που ηρεμούν την επιδερμίδα πριν τα πιο στοχευμένα βήματα.', 'A Korean in-between step, richer than a toner and thinner than a serum. It adds water and soothing ingredients before the more targeted steps.', 'essence', array['snail mucin','centella asiatica','hyaluronic acid','fermented extracts']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['all']::text[], array['hydration','redness','general']::text[], 'both', 'mid', 'Προαιρετικό βήμα: αν η ρουτίνα σου έχει ήδη ενυδατικό τόνερ και ορό, η essence προσθέτει λίγα.', 'An optional step: if your routine already has a hydrating toner and a serum, an essence adds little.'),
  ('dcba2e52-f505-37cb-fe81-f21b8f40d890'::uuid, 'exfoliant-aha-glycolic-lactic', 'Χημική απολέπιση AHA (γλυκολικό / γαλακτικό)', 'AHA chemical exfoliant (glycolic / lactic)', 'Υδατοδιαλυτά οξέα που χαλαρώνουν τους δεσμούς των νεκρών κυττάρων στην επιφάνεια: λάμψη, πιο λεία υφή, ομοιόμορφη απόχρωση. Το γαλακτικό είναι πιο ήπιο από το γλυκολικό.', 'Water-soluble acids that loosen the bonds between dead surface cells: glow, smoother texture, more even tone. Lactic acid is gentler than glycolic.', 'exfoliant', array['glycolic acid','lactic acid','mandelic acid']::text[], array['retinol in the same session','bha in the same session','vitamin c in the same session']::text[], array['us','eu','global']::text[], array['all']::text[], array['normal','dry','combination']::text[], array['texture','pigmentation','aging']::text[], 'pm', 'mid', 'Στην ΕΕ τα AHA σε καλλυντικά περιορίζονται σε περίπου 10 % και pH ≥ 3,5. Αυξάνουν τη φωτοευαισθησία — αντηλιακό το επόμενο πρωί είναι υποχρεωτικό.', 'In the EU cosmetic AHAs are limited to about 10 % at pH 3.5 or above. They increase photosensitivity — sunscreen the next morning is non-negotiable.'),
  ('c9e532cb-1ed7-3304-ee93-0b201a0a49aa'::uuid, 'exfoliant-bha-salicylic', 'Χημική απολέπιση BHA (σαλικυλικό οξύ)', 'BHA chemical exfoliant (salicylic acid)', 'Λιποδιαλυτό οξύ που μπαίνει μέσα στον πόρο και διαλύει σμήγμα και νεκρά κύτταρα. Η κλασική επιλογή για μαύρα στίγματα, κλειστά κομεδόνια και λιπαρή ζώνη Τ.', 'An oil-soluble acid that gets inside the pore and dissolves sebum and dead cells. The classic pick for blackheads, closed comedones and an oily T-zone.', 'exfoliant', array['salicylic acid','betaine salicylate','willow bark extract']::text[], array['retinol in the same session','aha in the same session']::text[], array['us','kr','global']::text[], array['all']::text[], array['oily','combination']::text[], array['acne','pores','texture']::text[], 'pm', 'mid', 'Στην Κορέα συχνά συναντάς «betaine salicylate», πιο ήπια μορφή. Όχι σε αλλεργία στην ασπιρίνη (σαλικυλικά).', 'In Korea you often see “betaine salicylate”, a gentler form. Not for people allergic to aspirin (salicylates).'),
  ('e212ff9f-b553-3c8f-d794-fa5ab5fdfd99'::uuid, 'exfoliant-enzyme-powder', 'Ενζυμική απολέπιση / σκόνη καθαρισμού', 'Enzyme exfoliant / cleansing powder', 'Ιαπωνικού τύπου σκόνη με πρωτεολυτικά ένζυμα (παπαΐνη, βρωμελίνη, πρωτεάση) που ενεργοποιείται με νερό και «τρώει» τα νεκρά κύτταρα. Πολύ ήπια εναλλακτική των οξέων.', 'A Japanese-style powder with proteolytic enzymes (papain, bromelain, protease) activated with water that digests dead cells. A very gentle alternative to acids.', 'exfoliant', array['papain','bromelain','protease','rice bran']::text[], '{}'::text[], array['jp']::text[], array['all']::text[], array['all']::text[], array['texture','pores']::text[], 'pm', 'mid', 'Ανακάτεψε με λίγο νερό στην παλάμη μέχρι να αφρίσει ελαφρά· 1–3 φορές την εβδομάδα.', 'Mix with a little water in your palm until it foams lightly; one to three times a week.'),
  ('463077b8-3a7b-10c4-c2a1-f9d3c4939d6e'::uuid, 'exfoliant-pha-gentle', 'Ήπια απολέπιση PHA (γλουκονολακτόνη)', 'Gentle PHA exfoliant (gluconolactone)', 'Πολυυδροξυοξέα με μεγαλύτερο μόριο που δουλεύουν μόνο στην επιφάνεια και ενυδατώνουν ταυτόχρονα. Το σημείο εκκίνησης για ευαίσθητη επιδερμίδα ή ροδόχρου ακμή.', 'Polyhydroxy acids with a larger molecule that work only at the surface and hydrate at the same time. The starting point for sensitive or rosacea-prone skin.', 'exfoliant', array['gluconolactone','lactobionic acid','glycerin']::text[], array['retinol in the same session']::text[], array['kr','eu']::text[], array['all']::text[], array['sensitive','dry']::text[], array['texture','redness','hydration']::text[], 'pm', 'mid', 'Ακόμη και τα PHA απολεπίζουν: 1–2 φορές την εβδομάδα αρκούν, όχι κάθε βράδυ.', 'Even PHAs exfoliate: once or twice a week is enough, not every night.'),
  ('50e7944c-d2ac-29b5-1f14-f91772a9d313'::uuid, 'eye-cream-caffeine', 'Κρέμα ματιών με καφεΐνη', 'Caffeine eye cream', 'Ελαφριά κρέμα ή gel για πρήξιμο και κούραση κάτω από τα μάτια· η καφεΐνη συσφίγγει προσωρινά τα αγγεία. Τα κληρονομικά σκούρα κύκλοι δεν αλλάζουν με κρέμα.', 'A light cream or gel for puffiness and tired under-eyes; caffeine constricts vessels for a while. Hereditary dark circles do not change with a cream.', 'eye', array['caffeine','hyaluronic acid','peptides','niacinamide']::text[], '{}'::text[], array['global','kr']::text[], array['all']::text[], array['all']::text[], array['aging','hydration']::text[], 'both', 'mid', 'Μια απλή ενυδατική χωρίς άρωμα κάνει σχεδόν την ίδια δουλειά· η κρέμα ματιών είναι επιλογή άνεσης, όχι ανάγκη.', 'A plain fragrance-free moisturiser does nearly the same job; an eye cream is a comfort choice, not a need.'),
  ('bddcda9e-e0b8-4456-347b-c2a1e6675a20'::uuid, 'eye-cream-retinal', 'Κρέμα ματιών με ρετινάλη', 'Retinal eye cream', 'Χαμηλή συγκέντρωση ρετιναλδεΰδης ή ρετινόλης σε πλούσια βάση, για λεπτές γραμμές στο λεπτό δέρμα των ματιών. Το βράδυ, 2–3 φορές την εβδομάδα στην αρχή.', 'A low concentration of retinaldehyde or retinol in a rich base, for fine lines on the thin eye-area skin. Evenings, two or three times a week at first.', 'eye', array['retinaldehyde','retinol','ceramides','peptides']::text[], array['aha or bha around the eyes','pregnancy and breastfeeding']::text[], array['eu','us']::text[], array['all']::text[], array['normal','dry','combination']::text[], array['aging']::text[], 'pm', 'high', 'Μέχρι το οστό της κόγχης, όχι στο βλέφαρο· αν ξεφλουδίσει, κάνε παύση.', 'Up to the orbital bone, never on the lid; if it peels, pause.'),
  ('644c2fba-188c-0778-0546-e04ed2e8411c'::uuid, 'hand-cream-urea', 'Κρέμα χεριών με ουρία', 'Hand cream with urea', 'Κρέμα χεριών με ουρία 5–10 %, γλυκερίνη και κλειστικά, που ενυδατώνει βαθιά και μαλακώνει σκληρύνσεις και σκασμένα δάχτυλα. Μετά από κάθε πλύσιμο και πριν τον ύπνο, μέχρι τα επωνύχια.', 'A hand cream with 5–10 % urea, glycerin and occlusives that hydrates deeply and softens calluses and cracked fingertips. After every wash and before bed, right up to the cuticles.', 'hand_cream', array['urea','glycerin','shea butter','ceramides','dimethicone']::text[], '{}'::text[], array['eu','global']::text[], array['all']::text[], array['dry','all']::text[], array['hands','nails','hydration']::text[], 'both', 'low', 'Οι ευρωπαϊκές φαρμακευτικές σειρές με ουρία είναι εδώ από τις πιο δοκιμασμένες· πάνω από 10 % η ουρία κερατολύει και προορίζεται για πέλματα.', 'European pharmacy lines with urea are among the best-proven here; above 10 % urea is keratolytic and meant for feet.'),
  ('2b1eca82-f6c4-16f1-0320-27190a75f68b'::uuid, 'lip-balm-spf', 'Βάλσαμο χειλιών με SPF', 'Lip balm with SPF', 'Τα χείλη δεν έχουν μελανίνη και καίγονται εύκολα· ένα βάλσαμο με SPF 30 και κλειστικά συστατικά τα προστατεύει και τα κρατά μαλακά. Επανεφαρμογή συχνά — τρώγεται και πίνεται.', 'Lips have no melanin and burn easily; an SPF 30 balm with occlusives protects them and keeps them soft. Reapply often — it gets eaten and drunk off.', 'lip', array['petrolatum','beeswax','zinc oxide','shea butter']::text[], '{}'::text[], array['global']::text[], array['all']::text[], array['all']::text[], array['sun','hydration']::text[], 'both', 'low', 'Απόφυγε βάλσαμα με μενθόλη, καμφορά ή άρωμα αν τα χείλη σκάνε συχνά.', 'Skip balms with menthol, camphor or fragrance if your lips chap often.'),
  ('41f0b620-645f-05d8-3463-cf3ade6ec6d9'::uuid, 'lip-sleeping-mask', 'Μάσκα χειλιών νύχτας', 'Lip sleeping mask', 'Πυκνό κορεατικό βάλσαμο που μένει όλη νύχτα και επανορθώνει σκασμένα χείλη, συχνά με ήπια απολεπιστικά σάκχαρα. Το πρωί σκουπίζεις τα νεκρά κύτταρα με πετσέτα.', 'A thick Korean balm left on all night to repair chapped lips, often with mild exfoliating sugars. In the morning the loosened flakes wipe off with a towel.', 'lip', array['shea butter','murumuru butter','vitamin c','hyaluronic acid']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['all']::text[], array['hydration']::text[], 'pm', 'mid', 'Ένα απλό στρώμα βαζελίνης το βράδυ κάνει σχεδόν το ίδιο για ένα κλάσμα της τιμής.', 'A plain layer of petrolatum at night does nearly the same for a fraction of the price.'),
  ('feb47211-b987-258f-25a8-75b5d9c84389'::uuid, 'mask-clay', 'Μάσκα αργίλου', 'Clay mask', 'Καολίνης ή μπεντονίτης που απορροφούν σμήγμα και «τραβούν» από τους πόρους. Για λιπαρή ζώνη Τ, 1 φορά την εβδομάδα, 10 λεπτά — όχι μέχρι να σκάσει.', 'Kaolin or bentonite that absorb sebum and draw from the pores. For an oily T-zone, once a week, ten minutes — not until it cracks.', 'mask', array['kaolin','bentonite','charcoal','zinc oxide']::text[], array['aha or bha the same evening']::text[], array['us','eu','global']::text[], array['all']::text[], array['oily','combination']::text[], array['pores','acne']::text[], 'pm', 'low', 'Το «multi-masking» — άργιλος στη μύτη, ενυδατική μάσκα στα μάγουλα — ταιριάζει στη μικτή επιδερμίδα.', 'Multi-masking — clay on the nose, a hydrating mask on the cheeks — suits combination skin.'),
  ('f26c4d4b-ef67-58c3-66e1-5256b9085e98'::uuid, 'mask-sheet', 'Υφασμάτινη μάσκα (sheet mask)', 'Sheet mask', 'Το σήμα κατατεθέν της κορεατικής περιποίησης: χαρτί ή βιοκυτταρίνη εμποτισμένη με ορό, 15–20 λεπτά, κυρίως για ενυδάτωση και άμεση φρεσκάδα.', 'The signature of Korean skincare: paper or bio-cellulose soaked in serum for 15–20 minutes, mainly for hydration and an instant refresh.', 'mask', array['hyaluronic acid','glycerin','centella asiatica extract','tea tree']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['all']::text[], array['hydration','general']::text[], 'pm', 'low', 'Μην την αφήνεις να στεγνώσει πάνω σου — μετά «τραβά» νερό πίσω. Μετά, ενυδατική για να σφραγίσει.', 'Do not let it dry on your face — it then pulls water back out. Follow with moisturiser to seal.'),
  ('25a7dc0a-5f21-72b6-00a6-f3865c3f5b76'::uuid, 'mask-sleeping-overnight', 'Μάσκα νύχτας (sleeping mask)', 'Sleeping (overnight) mask', 'Κορεατικό τελευταίο βήμα της βραδινής ρουτίνας, μια πιο πυκνή κρέμα-gel που μένει όλη νύχτα και ξεπλένεται το πρωί. Ενυδάτωση και επισκευή χωρίς τη βαρύτητα του βάλσαμου.', 'A Korean final evening step — a thicker cream-gel that stays on all night and rinses off in the morning. Hydration and repair without the heaviness of a balm.', 'mask', array['glycerin','ceramides','hyaluronic acid','squalane']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['dry','normal','combination']::text[], array['hydration','aging']::text[], 'pm', 'mid', 'Δύο-τρεις νύχτες την εβδομάδα στη θέση της κρέμας, όχι επιπλέον.', 'Two or three nights a week instead of your cream, not on top of it.'),
  ('a92c1a3c-a7e0-f8fa-98d0-5eb22bd3eaa9'::uuid, 'moisturizer-cream-ceramide', 'Κρέμα με κεραμίδια (επισκευή φραγμού)', 'Ceramide barrier cream', 'Πλούσια κρέμα που αναπληρώνει τα λιπίδια του δερματικού φραγμού — κεραμίδια, χοληστερόλη, λιπαρά οξέα. Για ξηρή, ερεθισμένη ή «κουρασμένη από ενεργά» επιδερμίδα και για τον χειμώνα με θέρμανση.', 'A rich cream that replenishes the barrier’s lipids — ceramides, cholesterol, fatty acids. For dry, irritated or “over-exfoliated” skin and for heated winter rooms.', 'moisturizer', array['ceramide np','cholesterol','fatty acids','glycerin','petrolatum']::text[], '{}'::text[], array['eu','us','global']::text[], array['all']::text[], array['dry','sensitive','normal']::text[], array['hydration','redness','aging']::text[], 'both', 'mid', 'Οι «δερμοκαλλυντικές» σειρές των ευρωπαϊκών φαρμακείων συνήθως εδώ ξεχωρίζουν: λίγα συστατικά, χωρίς άρωμα.', 'European pharmacy “dermo-cosmetic” lines usually shine here: few ingredients, no fragrance.'),
  ('97f40bbc-0263-ad00-51c0-d378496471f8'::uuid, 'moisturizer-emulsion-light', 'Ελαφρύ γαλάκτωμα (emulsion)', 'Light emulsion', 'Λεπτόρρευστη ενυδατική ανάμεσα σε λοσιόν και κρέμα, τυπική της κορεατικής και ιαπωνικής ρουτίνας. «Σφραγίζει» τόνερ και ορό χωρίς βάρος, ιδανική σε ζέστη και υγρασία.', 'A fluid moisturiser between a lotion and a cream, typical of Korean and Japanese routines. It seals toner and serum without weight — ideal in heat and humidity.', 'moisturizer', array['glycerin','squalane','ceramides','green tea extract']::text[], '{}'::text[], array['kr','jp']::text[], array['all']::text[], array['combination','normal','oily']::text[], array['hydration','general']::text[], 'both', 'mid', 'Τον χειμώνα πολλοί προσθέτουν κρέμα από πάνω και κρατούν το γαλάκτωμα για το καλοκαίρι.', 'In winter many add a cream on top and keep the emulsion for summer.'),
  ('0c12c6de-464d-52bd-959f-b3f791b34018'::uuid, 'moisturizer-gel-oil-free', 'Ενυδατική gel (χωρίς έλαια)', 'Oil-free gel moisturiser', 'Υδατική ενυδατική που απορροφάται γρήγορα και δεν αφήνει γυαλάδα· η λύση για λιπαρή επιδερμίδα και ελληνικά καλοκαίρια. Συνδυάζεται άνετα με αντηλιακό από πάνω.', 'A water-based moisturiser that absorbs fast and leaves no shine; the answer for oily skin and Greek summers. It layers easily under sunscreen.', 'moisturizer', array['glycerin','hyaluronic acid','niacinamide','dimethicone']::text[], '{}'::text[], array['global','us']::text[], array['all']::text[], array['oily','combination']::text[], array['hydration','acne','pores']::text[], 'both', 'low', 'Η λιπαρή επιδερμίδα χρειάζεται ενυδάτωση: όταν την παραλείπεις, το δέρμα συχνά παράγει περισσότερο σμήγμα.', 'Oily skin still needs moisture: skip it and the skin often produces more sebum.'),
  ('cc449025-a109-6143-8271-6bfbd2c19b19'::uuid, 'moisturizer-occlusive-balm', 'Κλειστικό βάλσαμο (slugging)', 'Occlusive balm (slugging)', 'Λεπτή στρώση βαζελίνης ή πυκνού βάλσαμου ως τελευταίο βήμα το βράδυ, που περιορίζει την απώλεια νερού. Για ξηρές ή πληγωμένες από ενεργά επιδερμίδες, όχι για ακμή.', 'A thin layer of petrolatum or a thick balm as the last evening step to cut water loss. For dry or active-stressed skin, not for acne-prone skin.', 'moisturizer', array['petrolatum','lanolin','shea butter','squalane']::text[], array['retinol underneath (traps it)','aha or bha underneath']::text[], array['us','kr','global']::text[], array['all']::text[], array['dry','sensitive']::text[], array['hydration','redness']::text[], 'pm', 'low', 'Πάνω από καθαρή, ενυδατωμένη επιδερμίδα· σε λιπαρή ή με σπυράκια συχνά φέρνει έξαρση.', 'Over clean, moisturised skin; on oily or blemish-prone skin it often triggers a flare.'),
  ('7c745775-8ba1-a520-a969-e6d54b09eb52'::uuid, 'nail-file-buffer-block', 'Μπλοκ γυαλίσματος (buffer)', 'Buffer block', 'Τετράπλευρο σφουγγάρι με διαβαθμίσεις που λειαίνει τις ραβδώσεις και δίνει φυσική γυαλάδα χωρίς βερνίκι — η πιο «αντρική» εκδοχή του μανικιούρ. Ελαφρά, όχι πάνω από 1–2 φορές τον μήνα.', 'A four-sided sponge of graded grits that smooths ridges and gives a natural shine without polish — the most “masculine” version of a manicure. Lightly, no more than once or twice a month.', 'nail_file', array['foam block','graded abrasive']::text[], array['buffing weekly (thins the plate)']::text[], array['global']::text[], array['men','all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'low', 'Το συχνό γυάλισμα λεπταίνει την πλάκα· αν τα νύχια γίνουν μαλακά, σταμάτα για έναν μήνα.', 'Frequent buffing thins the plate; if your nails go soft, stop for a month.'),
  ('50bb0e5a-4f7c-f618-9b41-14a5535b178c'::uuid, 'nail-file-glass', 'Γυάλινη (κρυστάλλινη) λίμα', 'Glass (crystal) nail file', 'Λίμα από σκληρυμένο γυαλί με πολύ λεπτή επιφάνεια που «σφραγίζει» την άκρη του νυχιού αντί να το ξεφτίζει όπως οι χάρτινες λίμες. Πλένεται και κρατά χρόνια.', 'A tempered-glass file with a very fine surface that seals the nail edge instead of fraying it like emery boards do. Washable and lasts for years.', 'nail_file', array['tempered glass']::text[], array['sawing back and forth']::text[], array['global','eu']::text[], array['all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'low', 'Λιμάρισμα προς μία κατεύθυνση, σε στεγνό νύχι· το βρεγμένο νύχι σκίζεται ευκολότερα.', 'File in one direction on a dry nail; a wet nail tears more easily.'),
  ('588b5027-ab2f-dba1-2d53-19f386840045'::uuid, 'nail-remover-acetone-free', 'Ασετόν-free αφαιρετικό βερνικιού', 'Acetone-free nail polish remover', 'Αφαιρετικό με οξικό αιθυλεστέρα ή ανθρακικό προπυλένιο και ελαφρά έλαια, πιο ήπιο για πλάκα και επωνύχια από την καθαρή ασετόν. Αργεί λίγο περισσότερο και δεν αφαιρεί gel.', 'A remover with ethyl acetate or propylene carbonate and light oils, gentler on the plate and cuticles than pure acetone. It takes a little longer and does not remove gel.', 'nail_remover', array['ethyl acetate','propylene carbonate','glycerin','sweet almond oil']::text[], '{}'::text[], array['global','eu']::text[], array['women','all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'low', 'Για gel ή ακρυλικό χρειάζεται ασετόν — αλλά με λάδι επωνυχίων πριν και κρέμα μετά, και όχι ξύσιμο.', 'Gel or acrylic needs acetone — but with cuticle oil before and hand cream after, and never scraping.'),
  ('b2f44a7b-d28d-fd0d-370e-a6b1def51a22'::uuid, 'nail-treatment-strengthener-keratin', 'Ενισχυτική θεραπεία νυχιών (κερατίνη / πεπτίδια)', 'Nail strengthener (keratin / peptides)', 'Διάφανο βερνίκι-θεραπεία με υδρολυμένη κερατίνη, πανθενόλη ή πεπτίδια που «γεμίζει» τις ρωγμές της πλάκας και μειώνει το σκίσιμο στις άκρες. Για κύκλο 4–6 εβδομάδων, κατά προτίμηση χωρίς φορμαλδεΰδη.', 'A clear treatment polish with hydrolysed keratin, panthenol or peptides that fills micro-cracks in the plate and reduces peeling at the tips. For a four-to-six-week course, preferably formaldehyde-free.', 'nail_treatment', array['hydrolysed keratin','panthenol','calcium pantothenate','peptides']::text[], array['formaldehyde hardeners for more than a few weeks']::text[], array['global','eu']::text[], array['all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'mid', 'Οι «σκληρυντές» με φορμαλδεΰδη κάνουν το νύχι πιο σκληρό αλλά και πιο εύθρυπτο με τον καιρό· στην ΕΕ η φορμαλδεΰδη σε βερνίκια περιορίζεται αυστηρά.', 'Formaldehyde hardeners make the nail harder but more brittle over time; in the EU formaldehyde in nail products is tightly restricted.'),
  ('b56b601a-6e35-e1ae-7968-cb83eec25b20'::uuid, 'serum-azelaic-acid', 'Ορός ή κρέμα αζελαϊκού οξέος', 'Azelaic acid serum or cream', 'Ήπιο «ενεργό» (10 % χωρίς συνταγή στην ΕΕ) για κοκκινίλα, ροδόχρου ακμή, σπυράκια και σημάδια. Από τα λίγα δραστικά που θεωρούνται κατάλληλα και στην εγκυμοσύνη.', 'A gentle active (10 % over the counter in the EU) for redness, rosacea-prone skin, blemishes and marks. One of the few actives generally considered suitable in pregnancy.', 'serum', array['azelaic acid','niacinamide','allantoin']::text[], array['aha in the same session']::text[], array['eu','us']::text[], array['all']::text[], array['sensitive','combination','oily','normal']::text[], array['redness','acne','pigmentation']::text[], 'both', 'mid', 'Ένα ελαφρύ τσούξιμο τα πρώτα λεπτά είναι συνηθισμένο και υποχωρεί σε 1–2 εβδομάδες. Τα 15–20 % είναι φαρμακευτικά σκευάσματα με συνταγή.', 'A light tingle for the first minutes is common and fades within a week or two. The 15–20 % strengths are prescription medicines.'),
  ('9f621e4c-67ba-6940-399d-eb7b622116af'::uuid, 'serum-centella-cica', 'Ορός centella («cica»)', 'Centella (“cica”) serum', 'Κορεατικό καταπραϋντικό με εκχύλισμα Centella asiatica (μαδεκασσοσίδη, ασιατικοσίδη) που ηρεμεί κοκκινίλα και επισκευάζει τον φραγμό μετά από ενεργά ή ξύρισμα.', 'A Korean soother with Centella asiatica extract (madecassoside, asiaticoside) that calms redness and repairs the barrier after actives or shaving.', 'serum', array['centella asiatica extract','madecassoside','panthenol','allantoin']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['sensitive','all']::text[], array['redness','shaving','hydration']::text[], 'both', 'mid', 'Καλή επιλογή για τις «ήσυχες» βραδιές ανάμεσα σε ρετινόλη και οξέα.', 'A good pick for the “rest” evenings between retinol and acids.'),
  ('fe0cd60e-9ee5-d8c9-a2db-5c555dc5d215'::uuid, 'serum-hyaluronic-acid', 'Ορός υαλουρονικού οξέος', 'Hyaluronic acid serum', 'Υγροσκοπικός ορός που «κρατά» νερό στα επιφανειακά στρώματα και δίνει άμεσα πιο γεμάτη όψη. Εφαρμόζεται σε νωπή επιδερμίδα και πάντα σφραγίζεται με ενυδατική.', 'A humectant serum that holds water in the upper layers for an instantly plumper look. Apply to damp skin and always seal with a moisturiser.', 'serum', array['sodium hyaluronate','hyaluronic acid','glycerin','panthenol']::text[], '{}'::text[], array['global']::text[], array['all']::text[], array['all']::text[], array['hydration','aging']::text[], 'both', 'low', 'Σε πολύ ξηρό αέρα (θέρμανση, κλιματισμός) χωρίς ενυδατική από πάνω μπορεί να «τραβήξει» νερό από το δέρμα αντί από τον αέρα.', 'In very dry air (heating, air conditioning) without a moisturiser on top it can pull water from the skin rather than the air.'),
  ('2727e376-3f07-6479-fada-9b0df52a0499'::uuid, 'serum-niacinamide', 'Ορός νιασιναμίδης', 'Niacinamide serum', 'Βιταμίνη B3 σε 2–10 %: ρυθμίζει το σμήγμα, ενισχύει τον φραγμό και αμβλύνει τα σημάδια μετά από σπυράκια. Από τα πιο ανεκτά «ενεργά», πρωί και βράδυ.', 'Vitamin B3 at 2–10 %: it regulates sebum, strengthens the barrier and softens post-blemish marks. One of the best-tolerated actives, morning and evening.', 'serum', array['niacinamide','zinc pca','hyaluronic acid']::text[], '{}'::text[], array['global','us','kr']::text[], array['all']::text[], array['all']::text[], array['pores','pigmentation','acne','redness']::text[], 'both', 'low', 'Πάνω από 10 % δεν προσφέρει περισσότερα και αυξάνει την πιθανότητα κοκκινίλας. Ο συνδυασμός με βιταμίνη C είναι ασφαλής.', 'Above 10 % adds nothing and raises the chance of flushing. Pairing with vitamin C is fine.'),
  ('661bb5c1-07fc-78bd-aaa8-50ba1a5b09ed'::uuid, 'serum-peptides', 'Ορός πεπτιδίων', 'Peptide serum', 'Ορός με μικρές αλυσίδες αμινοξέων που «σηματοδοτούν» στο δέρμα ενυδάτωση και σφριγηλότητα. Ήπιο, ταιριάζει σε όσους δεν ανέχονται ρετινόλη.', 'A serum of short amino-acid chains that signal hydration and firmness to the skin. Gentle, and a fit for people who do not tolerate retinol.', 'serum', array['palmitoyl tripeptide','copper peptides','acetyl hexapeptide-8']::text[], array['vitamin c in the same session (copper peptides)']::text[], array['kr','us','global']::text[], array['all']::text[], array['all']::text[], array['aging','hydration']::text[], 'both', 'high', 'Οι ενδείξεις είναι πιο αδύναμες από ό,τι για τη ρετινόλη· θεώρησέ το συμπλήρωμα και όχι αντικατάσταση αντηλιακού και ρετινόλης.', 'The evidence is weaker than for retinol; treat it as a supplement, not a replacement for sunscreen and retinol.'),
  ('2a639a7f-9459-b10c-836a-4ce86aac37f0'::uuid, 'serum-retinol', 'Ορός ρετινόλης', 'Retinol serum', 'Παράγωγο βιταμίνης Α χωρίς συνταγή που επιταχύνει την ανανέωση των κυττάρων: λεπτές γραμμές, υφή, σημάδια ακμής. Το βράδυ, σε στεγνή επιδερμίδα, ξεκινώντας 1–2 φορές την εβδομάδα.', 'An over-the-counter vitamin A derivative that speeds cell turnover: fine lines, texture, acne marks. Evenings, on dry skin, starting once or twice a week.', 'serum', array['retinol','retinaldehyde','squalane','bisabolol']::text[], array['aha in the same session','bha in the same session','benzoyl peroxide','vitamin c in the same session','pregnancy and breastfeeding']::text[], array['us','eu','global']::text[], array['all']::text[], array['normal','combination','oily','dry']::text[], array['aging','texture','acne','pigmentation']::text[], 'pm', 'mid', 'Από το 2025 η ΕΕ περιορίζει τη ρετινόλη σε καλλυντικά προσώπου στο 0,3 %. Αποφεύγεται στην εγκυμοσύνη και τον θηλασμό· για ισχυρότερα ρετινοειδή χρειάζεται δερματολόγος.', 'Since 2025 the EU caps retinol in face cosmetics at 0.3 %. Avoid in pregnancy and breastfeeding; stronger retinoids need a dermatologist.'),
  ('61d01f86-e90e-45f1-8b92-a08b865f8d39'::uuid, 'serum-snail-mucin', 'Ορός βλεννίνης σαλιγκαριού', 'Snail mucin serum', 'Κολλώδης ενυδατικός ορός της κορεατικής αγοράς, με έκκριμα σαλιγκαριού πλούσιο σε γλυκοπρωτεΐνες και υαλουρονικό. Ενυδατώνει, απαλύνει και βοηθά στην επούλωση μικροτραυματισμών.', 'A tacky hydrating serum from the Korean market, with snail secretion rich in glycoproteins and hyaluronic acid. It hydrates, softens and helps minor marks heal.', 'serum', array['snail secretion filtrate','hyaluronic acid','allantoin']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['all']::text[], array['hydration','texture','acne']::text[], 'both', 'mid', 'Όσοι έχουν αλλεργία σε οστρακοειδή ή μαλάκια ας κάνουν patch test· υπάρχουν αναφορές διασταυρούμενης αντίδρασης.', 'Anyone allergic to shellfish or molluscs should patch test; cross-reactions have been reported.'),
  ('5c86a2a0-346f-14d2-1721-0314cee33800'::uuid, 'serum-vitamin-c', 'Ορός βιταμίνης C', 'Vitamin C serum', 'Αντιοξειδωτικός ορός για το πρωί: συμπληρώνει το αντηλιακό, φωτίζει και βοηθά στην ομοιόμορφη απόχρωση. Το L-ασκορβικό (10–20 %) είναι το πιο μελετημένο αλλά και το πιο ασταθές.', 'An antioxidant morning serum: it complements sunscreen, brightens and helps even out tone. L-ascorbic acid (10–20 %) is the best-studied form and the least stable.', 'serum', array['l-ascorbic acid','ascorbyl glucoside','ferulic acid','vitamin e']::text[], array['benzoyl peroxide','retinol in the same session']::text[], array['us','eu','global']::text[], array['all']::text[], array['normal','combination','oily']::text[], array['pigmentation','aging','sun']::text[], 'am', 'mid', 'Όταν ο ορός σκουραίνει προς πορτοκαλί-καφέ, έχει οξειδωθεί και δεν προσφέρει πια. Φύλαξέ τον μακριά από φως και ζέστη.', 'When the serum turns orange-brown it has oxidised and no longer works. Keep it away from light and heat.'),
  ('26f6badb-40b2-d48b-dc13-bc598721db39'::uuid, 'shaving-aftershave-balm', 'Βάλσαμο μετά το ξύρισμα (χωρίς οινόπνευμα)', 'Alcohol-free aftershave balm', 'Καταπραϋντική κρέμα-γαλάκτωμα για μετά το ξύρισμα, που ενυδατώνει και ηρεμεί αντί να «καίει» όπως οι παλιές κολόνιες με οινόπνευμα. Το βασικό βήμα κατά του ερεθισμού και των τριχών που μεγαλώνουν προς τα μέσα.', 'A soothing post-shave cream-lotion that hydrates and calms instead of “burning” like the old alcohol splashes. The key step against razor burn and ingrown hairs.', 'shaving', array['allantoin','panthenol','aloe vera','niacinamide','bisabolol']::text[], '{}'::text[], array['global','eu']::text[], array['men']::text[], array['all']::text[], array['shaving','redness','hydration']::text[], 'am', 'low', 'Το ξύρισμα είναι από μόνο του απολέπιση· άφησε τα οξέα για άλλο βράδυ, όχι την ίδια μέρα.', 'Shaving is itself an exfoliation; leave acids for another evening, not the same day.'),
  ('bb78b163-53f1-ed36-7040-3a591922e3e4'::uuid, 'shaving-cream-brush', 'Κρέμα ξυρίσματος (με πινέλο)', 'Shaving cream (brush lather)', 'Παραδοσιακή κρέμα που αφρίζει με πινέλο: σηκώνει την τρίχα, κρατά υγρασία και προστατεύει το δέρμα καλύτερα από τον αφρό σε σπρέι. Για ξύρισμα με ξυράφι πολλαπλών ή μονής λεπίδας.', 'A traditional cream lathered with a brush: it lifts the hair, holds moisture and protects the skin better than aerosol foam. For multi-blade or single-blade razors.', 'shaving', array['glycerin','stearic acid','coconut acid','aloe vera']::text[], '{}'::text[], array['eu','global']::text[], array['men']::text[], array['all']::text[], array['shaving','redness']::text[], 'am', 'low', 'Προτίμησε εκδοχές χωρίς άρωμα και μενθόλη αν κοκκινίζεις εύκολα.', 'Pick fragrance- and menthol-free versions if you redden easily.'),
  ('ea2cf6d2-4157-6a16-d763-a8fe1c9c9e3e'::uuid, 'shaving-pre-shave-oil', 'Έλαιο πριν το ξύρισμα', 'Pre-shave oil', 'Λίγες σταγόνες ελαφριού ελαίου πριν τον αφρό μαλακώνουν την τρίχα και αφήνουν το ξυράφι να γλιστρά. Βοηθά σε σκληρή γενειάδα και ευαίσθητο λαιμό.', 'A few drops of a light oil before the lather soften the hair and let the razor glide. Helpful for coarse stubble and a sensitive neck.', 'shaving', array['castor oil','jojoba oil','sunflower seed oil','vitamin e']::text[], '{}'::text[], array['global','eu']::text[], array['men']::text[], array['all']::text[], array['shaving','redness']::text[], 'am', 'mid', 'Ξύρισμα μετά το ντους, όταν η τρίχα είναι ήδη μαλακή από το ζεστό νερό.', 'Shave after the shower, when the hair is already softened by warm water.'),
  ('96bcc124-5f4e-d40c-5f31-54f862794469'::uuid, 'sunscreen-eu-modern-filters', 'Αντηλιακό ευρείας προστασίας με νέα ευρωπαϊκά φίλτρα', 'Broad-spectrum sunscreen with modern EU filters', 'Οργανικά φίλτρα νέας γενιάς (Tinosorb S/M, Mexoryl SX/XL, Uvinul A Plus) με ισχυρή κάλυψη UVA, φωτοσταθερά και χωρίς λευκό ίχνος. SPF 50+ με τον κύκλο UVA της ΕΕ στην ετικέτα.', 'New-generation organic filters (Tinosorb S/M, Mexoryl SX/XL, Uvinul A Plus) with strong, photostable UVA cover and no white cast. SPF 50+ with the EU UVA circle on the label.', 'sunscreen', array['bemotrizinol (tinosorb s)','bisoctrizole (tinosorb m)','ecamsule (mexoryl sx)','diethylamino hydroxybenzoyl hexyl benzoate']::text[], '{}'::text[], array['eu']::text[], array['all']::text[], array['all']::text[], array['sun','aging','pigmentation']::text[], 'am', 'mid', 'Ο κύκλος «UVA» της ΕΕ σημαίνει προστασία UVA τουλάχιστον το 1/3 του SPF. Τα περισσότερα από αυτά τα φίλτρα δεν έχουν ακόμη έγκριση FDA, γι’ αυτό λείπουν από τα αμερικανικά ράφια.', 'The EU “UVA” circle means UVA protection of at least one third of the SPF. Most of these filters still lack FDA approval, which is why US shelves do not carry them.'),
  ('c4ab8998-3bed-dac2-ceee-2411be69477b'::uuid, 'sunscreen-jp-gel-watery', 'Ιαπωνικό υδαρές gel αντηλιακό', 'Japanese watery gel sunscreen', 'Οι πιο ελαφριές υφές της αγοράς — σχεδόν νερό — με SPF50+ PA++++, συχνά ανθεκτικές σε ιδρώτα και νερό. Ιδανικές κάτω από μακιγιάζ ή σε άντρες που δεν θέλουν «να νιώθουν» το αντηλιακό.', 'The lightest textures on the market — almost water — at SPF50+ PA++++, often sweat- and water-resistant. Ideal under make-up or for men who do not want to “feel” sunscreen.', 'sunscreen', array['ethylhexyl methoxycinnamate','bemotrizinol','alcohol denat','hyaluronic acid']::text[], '{}'::text[], array['jp']::text[], array['all']::text[], array['oily','combination','normal']::text[], array['sun','pores']::text[], 'am', 'low', 'Πολλά περιέχουν οινόπνευμα για την αίσθηση δροσιάς· σε ξηρή ή ευαίσθητη επιδερμίδα μπορεί να τσούξει.', 'Many contain alcohol for the cooling feel; on dry or sensitive skin it may sting.'),
  ('7719ae39-2a01-21bf-fd6d-e612e532c5b6'::uuid, 'sunscreen-kr-pa-plus', 'Κορεατικό αντηλιακό SPF50+ PA++++', 'Korean sunscreen SPF50+ PA++++', 'Ελαφριές, ενυδατικές υφές (συχνά με centella ή υαλουρονικό) που νιώθουν σαν ενυδατική. Ο δείκτης PA δηλώνει την προστασία UVA· τέσσερα «+» είναι το μέγιστο.', 'Light, hydrating textures (often with centella or hyaluronic acid) that feel like a moisturiser. The PA grade states UVA protection; four pluses is the maximum.', 'sunscreen', array['ethylhexyl triazone','bemotrizinol','centella asiatica extract','niacinamide']::text[], '{}'::text[], array['kr']::text[], array['all']::text[], array['all']::text[], array['sun','hydration']::text[], 'am', 'low', 'Το PA++++ αντιστοιχεί σε PPD 16+. Βάζε αρκετή ποσότητα (περίπου δύο δάχτυλα για το πρόσωπο) — η ελαφριά υφή κάνει εύκολο να βάλεις πολύ λίγο.', 'PA++++ corresponds to PPD 16+. Use enough (about two finger-lengths for the face) — a light texture makes it easy to apply too little.'),
  ('9f6b4ed8-80e8-4c00-8ff9-dbc81f62b802'::uuid, 'sunscreen-mineral-zinc', 'Αντηλιακό με ορυκτά φίλτρα (οξείδιο ψευδαργύρου)', 'Mineral sunscreen (zinc oxide)', 'Οξείδιο ψευδαργύρου ή/και διοξείδιο τιτανίου που αντανακλούν και απορροφούν την ακτινοβολία. Ανεκτό από ευαίσθητες επιδερμίδες και ροδόχρου ακμή· μπορεί να αφήνει λευκό ίχνος.', 'Zinc oxide and/or titanium dioxide that reflect and absorb UV. Tolerated by sensitive and rosacea-prone skin; it may leave a white cast.', 'sunscreen', array['zinc oxide','titanium dioxide','iron oxides']::text[], '{}'::text[], array['us','global']::text[], array['all']::text[], array['sensitive','dry','normal']::text[], array['sun','redness','pigmentation']::text[], 'am', 'mid', 'Στις ΗΠΑ τα αντηλιακά είναι φάρμακα OTC υπό τον FDA και μόνο τα ορυκτά φίλτρα αναγνωρίζονται ως GRASE. Τα οξείδια σιδήρου βοηθούν και με το ορατό φως (μέλασμα).', 'In the US sunscreens are OTC drugs under the FDA and only the mineral filters are recognised as GRASE. Iron oxides also help against visible light (melasma).'),
  ('ce4cefd9-99f3-4ea4-5a70-0128d944fcc7'::uuid, 'sunscreen-stick-reapply', 'Αντηλιακό stick για επανεφαρμογή', 'Sunscreen stick for reapplication', 'Στερεό αντηλιακό για γρήγορη επανεφαρμογή πάνω από μακιγιάζ ή στην παραλία, χωρίς χέρια. Χρειάζονται πολλά περάσματα για να φτάσει την προστασία της ετικέτας.', 'A solid sunscreen for quick, hands-free reapplication over make-up or at the beach. It takes several passes to reach the labelled protection.', 'sunscreen', array['zinc oxide','homosalate','octocrylene','shea butter']::text[], '{}'::text[], array['us','kr','global']::text[], array['all']::text[], array['all']::text[], array['sun']::text[], 'am', 'mid', 'Συμπλήρωμα και όχι αντικατάσταση της πρωινής εφαρμογής: βοηθά στην επανεφαρμογή κάθε 2 ώρες στον ήλιο.', 'A supplement, not a replacement for the morning layer: it makes the two-hourly reapplication in the sun doable.'),
  ('2ab65325-27a1-9538-54be-f1c84bcd0efb'::uuid, 'toner-exfoliating-bha', 'Απολεπιστικό τόνερ με BHA', 'Exfoliating BHA toner', 'Λοσιόν με σαλικυλικό οξύ (συνήθως 0,5–2 %) που διεισδύει στους πόρους και διαλύει το σμήγμα. Αμερικανικού τύπου «ενεργό» βήμα για λιπαρή επιδερμίδα με μαύρα στίγματα.', 'A lotion with salicylic acid (usually 0.5–2 %) that gets into pores and dissolves sebum. A US-style “active” step for oily skin with blackheads.', 'toner', array['salicylic acid','glycerin','green tea extract']::text[], array['retinol in the same session','aha in the same session','benzoyl peroxide']::text[], array['us','global']::text[], array['all']::text[], array['oily','combination']::text[], array['acne','pores','texture']::text[], 'pm', 'mid', 'Στην ΕΕ το σαλικυλικό οξύ σε προϊόντα που παραμένουν στο δέρμα περιορίζεται στο 2 %. Ξεκίνα 2–3 φορές την εβδομάδα.', 'In the EU salicylic acid in leave-on products is capped at 2 %. Start two or three times a week.'),
  ('1288a1bf-9bb2-f11d-db36-98877caefd0f'::uuid, 'toner-hydrating', 'Ενυδατικό τόνερ (χωρίς οινόπνευμα)', 'Hydrating toner (alcohol-free)', 'Υδατικό στρώμα με υγροσκοπικά συστατικά που εφαρμόζεται σε ελαφρώς νωπή επιδερμίδα, πριν τον ορό. Στην κορεατική ρουτίνα συχνά «χτυπιέται» σε 2–3 στρώσεις.', 'A watery layer of humectants patted onto slightly damp skin before serum. In Korean routines it is often applied in two or three thin layers.', 'toner', array['hyaluronic acid','glycerin','panthenol','beta-glucan']::text[], '{}'::text[], array['kr','jp']::text[], array['all']::text[], array['all']::text[], array['hydration','general']::text[], 'both', 'low', 'Τα παλιά «στυπτικά» τόνερ με οινόπνευμα δεν προσφέρουν κάτι στις περισσότερες επιδερμίδες και ξηραίνουν.', 'Old-style alcohol “astringent” toners offer little to most skins and dry them out.'),
  ('e6914cc3-db57-7f69-e55f-db7ce037c308'::uuid, 'treatment-adapalene-otc', 'Αδαπαλένη 0,1 % (ρετινοειδές)', 'Adapalene 0.1 % (retinoid)', 'Ρετινοειδές τρίτης γενιάς που στις ΗΠΑ πωλείται χωρίς συνταγή από το 2016 για την ακμή· λιγότερο ερεθιστικό από την τρετινοΐνη. Στην ΕΕ χορηγείται με ιατρική συνταγή.', 'A third-generation retinoid sold over the counter in the US since 2016 for acne; less irritating than tretinoin. In the EU it is prescription-only.', 'treatment', array['adapalene']::text[], array['aha in the same session','bha in the same session','benzoyl peroxide (unless a combined product)','pregnancy and breastfeeding']::text[], array['us']::text[], array['all']::text[], array['oily','combination','normal']::text[], array['acne','texture']::text[], 'pm', 'low', 'Είναι φάρμακο, όχι καλλυντικό: στην Ελλάδα το γράφει ο δερματολόγος. Οι πρώτες 4–6 εβδομάδες μπορεί να φέρουν έξαρση πριν τη βελτίωση.', 'It is a medicine, not a cosmetic: in Greece a dermatologist prescribes it. The first four to six weeks can bring a flare before improvement.'),
  ('deb3a5a4-6fe8-8aa1-d101-27c8496f59af'::uuid, 'treatment-benzoyl-peroxide-spot', 'Τοπική θεραπεία με υπεροξείδιο του βενζοϋλίου', 'Benzoyl peroxide spot treatment', 'Αντιβακτηριακό gel 2,5–5 % για φλεγμονώδη σπυράκια, κλασικό της αμερικανικής αγοράς χωρίς συνταγή. Στην Ελλάδα και στην ΕΕ διατίθεται ως φάρμακο από το φαρμακείο.', 'An antibacterial 2.5–5 % gel for inflamed spots, a US drugstore classic. In Greece and the EU it is sold as a medicine through pharmacies.', 'treatment', array['benzoyl peroxide']::text[], array['retinol in the same session','vitamin c in the same session','bha in the same session']::text[], array['us']::text[], array['all']::text[], array['oily','combination']::text[], array['acne']::text[], 'pm', 'low', 'Ξεβάφει πετσέτες και μαξιλαροθήκες. Το 2,5 % δουλεύει σχεδόν όσο το 10 % με λιγότερο ερεθισμό. Επίμονη ακμή: δερματολόγος.', 'It bleaches towels and pillowcases. 2.5 % works almost as well as 10 % with less irritation. Persistent acne: see a dermatologist.'),
  ('bed8b224-90a5-c0f8-0036-a61e73194e2d'::uuid, 'treatment-hydrocolloid-patch', 'Αυτοκόλλητο υδροκολλοειδές για σπυράκια', 'Hydrocolloid pimple patch', 'Μικρό διάφανο επίθεμα από τη χειρουργική επιδεσμολογία που απορροφά υγρό από ανοιχτά σπυράκια, προστατεύει από το ξύσιμο και επιταχύνει την επούλωση. Κορεατική επινόηση που έγινε παγκόσμια.', 'A small clear dressing borrowed from wound care that absorbs fluid from open spots, stops picking and speeds healing. A Korean idea that went global.', 'treatment', array['hydrocolloid','salicylic acid (some)','tea tree (some)']::text[], '{}'::text[], array['kr','global']::text[], array['all']::text[], array['all']::text[], array['acne']::text[], 'pm', 'low', 'Δουλεύει σε σπυράκι με «κεφάλι», όχι σε βαθιές κύστεις. Σε καθαρό, στεγνό δέρμα, 6–8 ώρες.', 'Works on a spot with a head, not on deep cysts. On clean, dry skin for six to eight hours.')
insert into hygieia.skincare_routines (id, slug, area, name_el, name_en, audience, skin_type, region, time, intro_el, intro_en, steps, duration_min) values
  ('7f37595d-26c8-9308-3c12-c45eb066522e'::uuid, 'face-all-all-am-us-minimal', 'face', 'Το πρωινό τριών βημάτων για όλους — αμερικανικό μίνιμαλ', 'The three-step morning for everyone — US minimal', 'all', 'all', 'us', 'am', 'Αν δεν θέλεις καμία ρουτίνα, κράτα αυτή: καθάρισε, ενυδάτωσε, φόρεσε αντηλιακό. Το αντηλιακό είναι το μόνο βήμα που δεν διαπραγματεύεται κανένας δερματολόγος.', 'If you want no routine at all, keep this one: cleanse, moisturise, wear sunscreen. Sunscreen is the one step no dermatologist will negotiate on.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Ή κρεμώδες αν η επιδερμίδα σου είναι ξηρή.","note_en":"Or a cream cleanser if your skin is dry.","optional":false},{"order":2,"product_type_slug":"serum-niacinamide","note_el":"Το ένα «έξτρα» που αξίζει, όταν το θελήσεις.","note_en":"The one extra worth adding, when you feel like it.","optional":true},{"order":3,"product_type_slug":"moisturizer-emulsion-light","note_el":"Κρέμα αντί για γαλάκτωμα τον χειμώνα.","note_en":"A cream instead of an emulsion in winter.","optional":false},{"order":4,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Κάθε μέρα, και με συννεφιά· τα UVA περνούν τα σύννεφα και τα τζάμια.","note_en":"Every day, clouds included; UVA passes through clouds and glass.","optional":false},{"order":5,"product_type_slug":"sunscreen-stick-reapply","note_el":"Στην τσάντα για το μεσημέρι.","note_en":"In your bag for midday.","optional":true}]'::jsonb, 3),
  ('a19bc116-f42a-3e1a-77bb-3a2d7a1b335b'::uuid, 'face-all-all-pm-kr-ten-step', 'face', 'Η πλήρης κορεατική βραδινή ρουτίνα δέκα βημάτων', 'The full ten-step Korean evening routine', 'all', 'all', 'kr', 'pm', 'Η διάσημη ρουτίνα των δέκα βημάτων, όπως γίνεται στην πράξη: τα μισά βήματα είναι προαιρετικά και κανείς δεν τα κάνει όλα κάθε βράδυ. Είναι ένα μενού, όχι μια λίστα υποχρεώσεων.', 'The famous ten-step routine as it is actually done: half the steps are optional and nobody does all of them every night. It is a menu, not a checklist.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Πρώτος καθαρισμός, σε στεγνό πρόσωπο.","note_en":"First cleanse, on a dry face.","optional":false},{"order":2,"product_type_slug":"cleanser-gel-foaming","note_el":"Δεύτερος καθαρισμός.","note_en":"Second cleanse.","optional":false},{"order":3,"product_type_slug":"exfoliant-pha-gentle","note_el":"1–2 φορές την εβδομάδα.","note_en":"Once or twice a week.","optional":true},{"order":4,"product_type_slug":"toner-hydrating","note_el":"Δύο-τρεις στρώσεις.","note_en":"Two or three layers.","optional":false},{"order":5,"product_type_slug":"essence-first-treatment","note_el":"Το «πολυτελές» βήμα· παράλειψέ το άφοβα.","note_en":"The “luxury” step; skip it without guilt.","optional":true},{"order":6,"product_type_slug":"essence-hydrating","note_el":"Πίεσε με τις παλάμες.","note_en":"Press in with your palms.","optional":true},{"order":7,"product_type_slug":"serum-snail-mucin","note_el":"Ή όποιος ορός ταιριάζει στο δικό σου ζήτημα.","note_en":"Or whichever serum fits your own concern.","optional":false},{"order":8,"product_type_slug":"mask-sheet","note_el":"15–20 λεπτά, 1–2 φορές την εβδομάδα.","note_en":"15–20 minutes, once or twice a week.","optional":true},{"order":9,"product_type_slug":"moisturizer-emulsion-light","note_el":"Κάθε βράδυ.","note_en":"Every night.","optional":false},{"order":10,"product_type_slug":"mask-sleeping-overnight","note_el":"Στη θέση της κρέμας, 2–3 νύχτες την εβδομάδα.","note_en":"Instead of a cream, two or three nights a week.","optional":true}]'::jsonb, 25),
  ('778cb755-799d-fd5e-20ef-b44d0e5a72dc'::uuid, 'face-all-dry-pm-eu-winter', 'face', 'Χειμερινή επισκευή φραγμού — ευρωπαϊκό δερμοκαλλυντικό', 'Winter barrier repair — European dermo-cosmetic', 'all', 'dry', 'eu', 'pm', 'Για τις εβδομάδες με θέρμανση, κρύο αέρα και ξεφλούδισμα: καμία απολέπιση, καμία ρετινόλη, μόνο νερό, λιπίδια και ένα κλειστικό στρώμα για να μη χαθεί τίποτα μέσα στη νύχτα.', 'For the weeks of heating, cold air and flaking: no exfoliation, no retinol, just water, lipids and an occlusive layer so nothing is lost overnight.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Χλιαρό νερό· το ζεστό ντους ξηραίνει.","note_en":"Lukewarm water; a hot shower dries you out.","optional":false},{"order":2,"product_type_slug":"serum-hyaluronic-acid","note_el":"Σε νωπό δέρμα.","note_en":"On damp skin.","optional":false},{"order":3,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Διπλή δόση.","note_en":"A double dose.","optional":false},{"order":4,"product_type_slug":"moisturizer-occlusive-balm","note_el":"Λεπτή στρώση στα μάγουλα και γύρω από τη μύτη.","note_en":"A thin layer on the cheeks and around the nose.","optional":false},{"order":5,"product_type_slug":"lip-sleeping-mask","note_el":"Ή απλή βαζελίνη στα χείλη.","note_en":"Or plain petrolatum on the lips.","optional":true}]'::jsonb, 7),
  ('87227790-8d62-91f0-a182-b3b87bae8452'::uuid, 'face-all-oily-pm-us-acne', 'face', 'Βραδινή ρουτίνα για ακμή — αμερικανική «κλινική» προσέγγιση', 'Evening acne routine — US clinical approach', 'all', 'oily', 'us', 'pm', 'Η ρουτίνα που προτείνουν οι αμερικανικοί οδηγοί για ήπια ως μέτρια ακμή: ήπιος καθαρισμός, υπεροξείδιο του βενζοϋλίου στα σπυράκια, αδαπαλένη παντού, ενυδάτωση. Στην Ελλάδα η αδαπαλένη και το υπεροξείδιο χρειάζονται φαρμακείο ή συνταγή — μίλα με δερματολόγο πριν ξεκινήσεις.', 'The routine US guidelines suggest for mild to moderate acne: gentle cleanse, benzoyl peroxide on spots, adapalene all over, moisturise. In Greece adapalene and benzoyl peroxide need a pharmacy or a prescription — talk to a dermatologist before starting.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Όχι τρίψιμο, όχι «απολεπιστικά» σφουγγάρια.","note_en":"No scrubbing, no “exfoliating” sponges.","optional":false},{"order":2,"product_type_slug":"treatment-benzoyl-peroxide-spot","note_el":"Μόνο στα φλεγμονώδη σπυράκια, 2,5 %· άσπρη πετσέτα.","note_en":"Only on inflamed spots, 2.5 %; use a white towel.","optional":true},{"order":3,"product_type_slug":"treatment-adapalene-otc","note_el":"Ένα μπιζέλι για όλο το πρόσωπο, σε στεγνό δέρμα· 4–6 εβδομάδες για αποτέλεσμα.","note_en":"A pea for the whole face, on dry skin; four to six weeks to see results.","optional":false},{"order":4,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Κάθε βράδυ, χωρίς εξαίρεση — η ξηρότητα είναι η πρώτη αιτία παραίτησης.","note_en":"Every night, no exception — dryness is the top reason people quit.","optional":false},{"order":5,"product_type_slug":"treatment-hydrocolloid-patch","note_el":"Αντί να το πειράξεις.","note_en":"Instead of picking it.","optional":true}]'::jsonb, 8),
  ('df9a2964-6d46-dddf-4041-1385ac728914'::uuid, 'face-men-combination-am-jp', 'face', 'Πρωινή ρουτίνα για άντρες, μικτή επιδερμίδα — ιαπωνικό στιλ', 'Men’s morning routine, combination skin — Japanese style', 'men', 'combination', 'jp', 'am', 'Λιπαρή ζώνη Τ και πιο ξηρά μάγουλα: η ιαπωνική απάντηση είναι υφές που ενυδατώνουν χωρίς βάρος και ένα αντηλιακό σαν νερό που δεν φράζει τους πόρους.', 'An oily T-zone and drier cheeks: the Japanese answer is textures that hydrate without weight and a water-like sunscreen that does not clog.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Επικεντρώσου στη ζώνη Τ, πέρνα απαλά από τα μάγουλα.","note_en":"Focus on the T-zone, go lightly over the cheeks.","optional":false},{"order":2,"product_type_slug":"toner-hydrating","note_el":"Μία στρώση παντού.","note_en":"One layer all over.","optional":false},{"order":3,"product_type_slug":"moisturizer-emulsion-light","note_el":"Λίγο περισσότερο στα μάγουλα.","note_en":"A little more on the cheeks.","optional":false},{"order":4,"product_type_slug":"sunscreen-jp-gel-watery","note_el":"Ξαναβάλε το μεσημέρι αν είσαι έξω.","note_en":"Reapply at midday if you are outdoors.","optional":false}]'::jsonb, 5),
  ('b6cd6392-d61b-36c0-7fb6-5317c92895c5'::uuid, 'face-men-combination-pm-us', 'face', 'Βραδινή ρουτίνα για άντρες, μικτή επιδερμίδα — αμερικανικά «ενεργά»', 'Men’s evening routine, combination skin — US actives', 'men', 'combination', 'us', 'pm', 'Ένα «ενεργό» κάθε βράδυ, ποτέ δύο μαζί: BHA τις μισές μέρες της εβδομάδας, ρετινόλη τις άλλες, και ενυδάτωση πάντα. Αυτή η εναλλαγή είναι ο πυρήνας της αμερικανικής ρουτίνας.', 'One active per evening, never two together: BHA half the week, retinol the other half, and moisturiser always. That alternation is the core of the US routine.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Στέγνωσε καλά — η ρετινόλη μπαίνει σε στεγνό δέρμα.","note_en":"Dry well — retinol goes on dry skin.","optional":false},{"order":2,"product_type_slug":"exfoliant-bha-salicylic","note_el":"Δευτέρα, Τετάρτη, Παρασκευή: μόνο στη ζώνη Τ.","note_en":"Monday, Wednesday, Friday: T-zone only.","optional":true},{"order":3,"product_type_slug":"serum-retinol","note_el":"Τρίτη, Πέμπτη, Σάββατο· ένα μπιζέλι για όλο το πρόσωπο.","note_en":"Tuesday, Thursday, Saturday; a pea-sized amount for the whole face.","optional":false},{"order":4,"product_type_slug":"eye-cream-caffeine","note_el":"Προαιρετικό· μια απλή ενυδατική κάνει σχεδόν το ίδιο.","note_en":"Optional; a plain moisturiser does nearly the same.","optional":true},{"order":5,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Κυριακή: μόνο καθαρισμός και ενυδατική — ρεπό για το δέρμα.","note_en":"Sunday: just cleanse and moisturise — a rest day for the skin.","optional":false}]'::jsonb, 8),
  ('8aef3873-42ec-450d-e972-e8234c2decc1'::uuid, 'face-men-dry-am-eu', 'face', 'Πρωινή ρουτίνα για άντρες, ξηρή επιδερμίδα — ευρωπαϊκό μίνιμαλ', 'Men’s morning routine, dry skin — European minimal', 'men', 'dry', 'eu', 'am', 'Η ξηρή επιδερμίδα δεν χρειάζεται δυνατό πρωινό καθάρισμα· χρειάζεται νερό, λιπίδια και αντηλιακό υψηλής προστασίας με τα σύγχρονα ευρωπαϊκά φίλτρα.', 'Dry skin does not need a strong morning wash; it needs water, lipids and a high-protection sunscreen with the modern European filters.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ή μόνο χλιαρό νερό, αν το δέρμα το προτιμά.","note_en":"Or lukewarm water alone, if your skin prefers it.","optional":true},{"order":2,"product_type_slug":"serum-hyaluronic-acid","note_el":"Σε νωπό δέρμα — αυτό είναι το μυστικό του.","note_en":"On damp skin — that is the whole trick.","optional":false},{"order":3,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Περίμενε να απορροφηθεί πριν το αντηλιακό.","note_en":"Let it absorb before the sunscreen.","optional":false},{"order":4,"product_type_slug":"sunscreen-eu-modern-filters","note_el":"SPF 50+ με τον κύκλο UVA στη συσκευασία.","note_en":"SPF 50+ with the UVA circle on the pack.","optional":false}]'::jsonb, 5),
  ('643306da-83b0-f3fc-1518-45641fd3d188'::uuid, 'face-men-dry-pm-kr', 'face', 'Βραδινή ρουτίνα για άντρες, ξηρή επιδερμίδα — κορεατικές στρώσεις', 'Men’s evening routine, dry skin — Korean layering', 'men', 'dry', 'kr', 'pm', 'Η κορεατική προσέγγιση για ξηρή επιδερμίδα: πολλές λεπτές υδατικές στρώσεις αντί για μία παχιά κρέμα. Κάθε στρώση «πατάει» στην προηγούμενη όσο είναι ακόμη νωπή.', 'The Korean approach to dry skin: many thin watery layers instead of one thick cream. Each layer goes on while the previous one is still damp.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Πρώτος καθαρισμός, μόνο αν φόρεσες αντηλιακό.","note_en":"First cleanse, only if you wore sunscreen.","optional":true},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Δεύτερος καθαρισμός, ήπιος.","note_en":"Second cleanse, gentle.","optional":false},{"order":3,"product_type_slug":"toner-hydrating","note_el":"Δύο στρώσεις, με τις παλάμες.","note_en":"Two layers, with your palms.","optional":false},{"order":4,"product_type_slug":"serum-snail-mucin","note_el":"Κολλώδες στην αρχή — απορροφάται σε ένα λεπτό.","note_en":"Tacky at first — it sinks in within a minute.","optional":false},{"order":5,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Σφράγισε όλες τις στρώσεις.","note_en":"Seal every layer in.","optional":false},{"order":6,"product_type_slug":"moisturizer-occlusive-balm","note_el":"Λεπτή στρώση στα μάγουλα τις πολύ ξηρές νύχτες.","note_en":"A thin layer on the cheeks on very dry nights.","optional":true}]'::jsonb, 12),
  ('b796cc3a-124f-b73d-d233-b9bd8d03b08d'::uuid, 'face-men-normal-am-jp', 'face', 'Πρωινή ρουτίνα για άντρες, κανονική επιδερμίδα — ιαπωνικό στιλ', 'Men’s morning routine, normal skin — Japanese style', 'men', 'normal', 'jp', 'am', 'Τέσσερα ελαφριά βήματα που δεν «νιώθονται» πάνω στο δέρμα: καθαρισμός, ένα υδατικό στρώμα, γαλάκτωμα και το πιο υδαρές αντηλιακό της αγοράς. Πέντε λεπτά και είσαι έτοιμος.', 'Four light steps you will not feel on your skin: cleanse, one watery layer, an emulsion and the most water-like sunscreen on the market. Five minutes and you are done.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Χλιαρό νερό, 30 δευτερόλεπτα, χωρίς τρίψιμο.","note_en":"Lukewarm water, 30 seconds, no scrubbing.","optional":false},{"order":2,"product_type_slug":"toner-hydrating","note_el":"Λίγες σταγόνες στις παλάμες και πίεσε στο νωπό δέρμα.","note_en":"A few drops in your palms, pressed into damp skin.","optional":true},{"order":3,"product_type_slug":"moisturizer-emulsion-light","note_el":"Μια δόση όσο ένα φουντούκι, μέχρι τον λαιμό.","note_en":"A hazelnut-sized amount, down to the neck.","optional":false},{"order":4,"product_type_slug":"sunscreen-jp-gel-watery","note_el":"Δύο δάχτυλα ποσότητα· άφησέ το ένα λεπτό πριν βγεις.","note_en":"Two finger-lengths; give it a minute before heading out.","optional":false},{"order":5,"product_type_slug":"lip-balm-spf","note_el":"Τα χείλη καίγονται πρώτα στον ελληνικό ήλιο.","note_en":"Lips burn first under the Greek sun.","optional":true}]'::jsonb, 5),
  ('f1a87e59-ca6a-137c-a34b-2fd1df42bcb3'::uuid, 'face-men-normal-pm-eu', 'face', 'Βραδινή ρουτίνα για άντρες, κανονική επιδερμίδα — ευρωπαϊκό μίνιμαλ', 'Men’s evening routine, normal skin — European minimal', 'men', 'normal', 'eu', 'pm', 'Η λογική του ευρωπαϊκού φαρμακείου: λίγα προϊόντα, χωρίς άρωμα, με έμφαση στον φραγμό. Καθάρισε, πρόσθεσε ένα ήπιο ενεργό αν θέλεις, σφράγισε με κρέμα.', 'The European pharmacy logic: few products, fragrance-free, barrier first. Cleanse, add one gentle active if you like, seal with a cream.', '[{"order":1,"product_type_slug":"cleanser-micellar-water","note_el":"Μόνο αν φόρεσες αντηλιακό ή ίδρωσες πολύ· αλλιώς πήγαινε στο βήμα 2.","note_en":"Only if you wore sunscreen or sweated a lot; otherwise go to step 2.","optional":true},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Ένα λεπτό μασάζ, ξέβγαλμα, ταμπονάρισμα με καθαρή πετσέτα.","note_en":"A one-minute massage, rinse, pat dry with a clean towel.","optional":false},{"order":3,"product_type_slug":"serum-niacinamide","note_el":"Τρεις-τέσσερις σταγόνες· το πιο ανεκτό «ενεργό» για αρχή.","note_en":"Three or four drops; the best-tolerated active to start with.","optional":true},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Πιο γενναιόδωρα τον χειμώνα με τη θέρμανση.","note_en":"More generously in winter when the heating is on.","optional":false}]'::jsonb, 6),
  ('3fb97e63-d1cc-1a27-40a1-22f576d6e015'::uuid, 'face-men-oily-am-us', 'face', 'Πρωινή ρουτίνα για άντρες, λιπαρή επιδερμίδα — αμερικανικά «ενεργά»', 'Men’s morning routine, oily skin — US actives', 'men', 'oily', 'us', 'am', 'Καθαρισμός, ένα συστατικό που ρυθμίζει το σμήγμα, ενυδάτωση χωρίς έλαια και ορυκτό αντηλιακό που δεν γυαλίζει. Αν ξυρίστηκες, το βάλσαμο μετά το ξύρισμα μπαίνει πριν την ενυδατική.', 'Cleanse, one sebum-regulating ingredient, oil-free hydration and a mineral sunscreen that does not shine. If you shaved, the aftershave balm goes on before the moisturiser.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Μετά το ντους ή το ξύρισμα.","note_en":"After the shower or shave.","optional":false},{"order":2,"product_type_slug":"shaving-aftershave-balm","note_el":"Μόνο τις μέρες που ξυρίζεσαι.","note_en":"Only on the days you shave.","optional":true},{"order":3,"product_type_slug":"serum-niacinamide","note_el":"Λιγότερη γυαλάδα μέσα στη μέρα μετά από λίγες εβδομάδες.","note_en":"Less midday shine after a few weeks.","optional":false},{"order":4,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Ναι, και η λιπαρή επιδερμίδα ενυδατώνεται.","note_en":"Yes, oily skin gets moisturised too.","optional":false},{"order":5,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Ματ φινίρισμα· διάλεξε «tinted» αν σε ενοχλεί το λευκό ίχνος.","note_en":"Matte finish; pick a tinted one if the white cast bothers you.","optional":false}]'::jsonb, 5),
  ('5ad0cf47-aa0a-6b31-41fb-95f59eaa27a5'::uuid, 'face-men-oily-pm-kr', 'face', 'Βραδινή ρουτίνα για άντρες, λιπαρή επιδερμίδα — κορεατικό στιλ', 'Men’s evening routine, oily skin — Korean style', 'men', 'oily', 'kr', 'pm', 'Διπλός καθαρισμός για να φύγει το αντηλιακό της μέρας, ήπια απολέπιση 2–3 φορές την εβδομάδα και καταπραϋντικές στρώσεις αντί για «στέγνωμα». Η κορεατική λογική για τη λιπαρή επιδερμίδα είναι ισορροπία, όχι πόλεμος.', 'A double cleanse to remove the day’s sunscreen, gentle exfoliation two or three times a week and soothing layers instead of “drying out”. The Korean logic for oily skin is balance, not war.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Ναι, λάδι σε λιπαρή επιδερμίδα: διαλύει σμήγμα και αντηλιακό.","note_en":"Yes, oil on oily skin: it dissolves sebum and sunscreen.","optional":false},{"order":2,"product_type_slug":"cleanser-gel-foaming","note_el":"Δεύτερος καθαρισμός.","note_en":"Second cleanse.","optional":false},{"order":3,"product_type_slug":"toner-exfoliating-bha","note_el":"2–3 βράδια την εβδομάδα, όχι κάθε μέρα.","note_en":"Two or three evenings a week, not daily.","optional":true},{"order":4,"product_type_slug":"toner-hydrating","note_el":"Τα υπόλοιπα βράδια, ή μετά το BHA αφού στεγνώσει.","note_en":"On the other evenings, or after the BHA once it has dried.","optional":false},{"order":5,"product_type_slug":"serum-centella-cica","note_el":"Ηρεμεί κοκκινίλες από σπυράκια και ξύρισμα.","note_en":"Calms redness from spots and shaving.","optional":false},{"order":6,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Λεπτή στρώση.","note_en":"A thin layer.","optional":false},{"order":7,"product_type_slug":"treatment-hydrocolloid-patch","note_el":"Πάνω σε σπυράκι με «κεφάλι», τελευταίο βήμα.","note_en":"On a spot with a head, as the last step.","optional":true}]'::jsonb, 12),
  ('acc95825-8134-67ae-f301-9fe8617a0e0e'::uuid, 'face-men-sensitive-am-eu', 'face', 'Πρωινή ρουτίνα για άντρες, ευαίσθητη επιδερμίδα — ξύρισμα χωρίς ερεθισμό', 'Men’s morning routine, sensitive skin — irritation-free shave', 'men', 'sensitive', 'eu', 'am', 'Για το ευαίσθητο δέρμα το πρόβλημα του πρωινού είναι συνήθως το ξύρισμα. Λάδι πριν, κρέμα με πινέλο, βάλσαμο μετά, κρέμα φραγμού και ορυκτό αντηλιακό χωρίς άρωμα.', 'For sensitive skin the morning problem is usually the shave. Oil before, brush-lathered cream, balm after, a barrier cream and a fragrance-free mineral sunscreen.', '[{"order":1,"product_type_slug":"shaving-pre-shave-oil","note_el":"Μετά το ντους, σε νωπή τρίχα.","note_en":"After the shower, on damp stubble.","optional":true},{"order":2,"product_type_slug":"shaving-cream-brush","note_el":"Ξύρισε με τη φορά της τρίχας, καθαρή λεπίδα.","note_en":"Shave with the grain, fresh blade.","optional":false},{"order":3,"product_type_slug":"shaving-aftershave-balm","note_el":"Κρύο ξέβγαλμα, μετά το βάλσαμο· τίποτα με οινόπνευμα.","note_en":"Cold rinse, then the balm; nothing with alcohol.","optional":false},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Τις μέρες χωρίς ξύρισμα: μόνο νερό, κρέμα, αντηλιακό.","note_en":"On non-shave days: just water, cream, sunscreen.","optional":false},{"order":5,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Τα ορυκτά φίλτρα τσούζουν λιγότερο σε φρεσκοξυρισμένο δέρμα.","note_en":"Mineral filters sting less on freshly shaved skin.","optional":false}]'::jsonb, 10),
  ('92a942f5-84d6-c4d2-60e4-0a8a93649263'::uuid, 'face-men-sensitive-pm-eu', 'face', 'Βραδινή ρουτίνα για άντρες, ευαίσθητη επιδερμίδα — επισκευή φραγμού', 'Men’s evening routine, sensitive skin — barrier repair', 'men', 'sensitive', 'eu', 'pm', 'Το βράδυ του ευαίσθητου δέρματος είναι για ξεκούραση: ήπιος καθαρισμός, ένα καταπραϋντικό και λιπίδια. Κανένα οξύ, καμία ρετινόλη μέχρι να ηρεμήσει η κοκκινίλα για δύο εβδομάδες.', 'Sensitive skin’s evening is for rest: a gentle cleanse, one soother and lipids. No acid, no retinol until the redness has been quiet for two weeks.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Χωρίς άρωμα· ξέβγαλμα με χλιαρό, όχι ζεστό νερό.","note_en":"Fragrance-free; rinse with lukewarm, not hot, water.","optional":false},{"order":2,"product_type_slug":"serum-centella-cica","note_el":"Ή αζελαϊκό 10 % αν έχεις και σπυράκια.","note_en":"Or 10 % azelaic acid if you also get spots.","optional":false},{"order":3,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Γενναιόδωρα.","note_en":"Generously.","optional":false},{"order":4,"product_type_slug":"moisturizer-occlusive-balm","note_el":"Στα σημεία που ξεφλουδίζουν, τις νύχτες με θέρμανση.","note_en":"On the flaky patches, on nights with the heating on.","optional":true}]'::jsonb, 6),
  ('784db642-11fc-04bc-27bf-4c10d38cccbb'::uuid, 'face-women-combination-am-kr', 'face', 'Πρωινή ρουτίνα για γυναίκες, μικτή επιδερμίδα — κορεατικό στιλ', 'Women’s morning routine, combination skin — Korean style', 'women', 'combination', 'kr', 'am', 'Υδατικές στρώσεις που ενυδατώνουν τα μάγουλα χωρίς να βαραίνουν τη ζώνη Τ, νιασιναμίδη για τους πόρους και ένα ελαφρύ αντηλιακό PA++++ που κάθεται σαν ενυδατική.', 'Watery layers that hydrate the cheeks without weighing down the T-zone, niacinamide for pores and a light PA++++ sunscreen that wears like a moisturiser.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Απαλά στα μάγουλα.","note_en":"Gently over the cheeks.","optional":false},{"order":2,"product_type_slug":"toner-hydrating","note_el":"Δύο στρώσεις.","note_en":"Two layers.","optional":false},{"order":3,"product_type_slug":"essence-hydrating","note_el":"Προαιρετικό όταν βιάζεσαι.","note_en":"Optional when you are in a hurry.","optional":true},{"order":4,"product_type_slug":"serum-niacinamide","note_el":"Παντού, με έμφαση στη μύτη και το μέτωπο.","note_en":"All over, with focus on the nose and forehead.","optional":false},{"order":5,"product_type_slug":"moisturizer-emulsion-light","note_el":"Λίγο περισσότερο στα μάγουλα.","note_en":"A little more on the cheeks.","optional":false},{"order":6,"product_type_slug":"sunscreen-kr-pa-plus","note_el":"Δύο δάχτυλα ποσότητα.","note_en":"Two finger-lengths.","optional":false}]'::jsonb, 8),
  ('1f2f5ba3-c352-b81c-145b-a1554fbbfa8a'::uuid, 'face-women-combination-pm-kr', 'face', 'Βραδινή ρουτίνα για γυναίκες, μικτή επιδερμίδα — κορεατικό στιλ', 'Women’s evening routine, combination skin — Korean style', 'women', 'combination', 'kr', 'pm', 'Οκτώ βήματα που δεν είναι όλα για κάθε βράδυ: διπλός καθαρισμός, ήπια απολέπιση PHA δύο φορές την εβδομάδα, στρώσεις ενυδάτωσης, καταπραϋντικός ορός και γαλάκτωμα — μάσκα ύπνου όταν το δέρμα το ζητά.', 'Eight steps that are not all for every night: double cleanse, gentle PHA twice a week, hydrating layers, a soothing serum and an emulsion — a sleeping mask when the skin asks for it.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Πρώτος καθαρισμός.","note_en":"First cleanse.","optional":false},{"order":2,"product_type_slug":"cleanser-gel-foaming","note_el":"Δεύτερος καθαρισμός.","note_en":"Second cleanse.","optional":false},{"order":3,"product_type_slug":"exfoliant-pha-gentle","note_el":"Δύο βράδια την εβδομάδα.","note_en":"Two evenings a week.","optional":true},{"order":4,"product_type_slug":"toner-hydrating","note_el":"Δύο στρώσεις.","note_en":"Two layers.","optional":false},{"order":5,"product_type_slug":"essence-hydrating","note_el":"Πίεσε με τις παλάμες.","note_en":"Press in with your palms.","optional":true},{"order":6,"product_type_slug":"serum-centella-cica","note_el":"Ηρεμεί τη ζώνη Τ μετά την απολέπιση.","note_en":"Calms the T-zone after exfoliation.","optional":false},{"order":7,"product_type_slug":"moisturizer-emulsion-light","note_el":"Παντού.","note_en":"All over.","optional":false},{"order":8,"product_type_slug":"mask-sleeping-overnight","note_el":"Μόνο στα μάγουλα, δύο νύχτες την εβδομάδα.","note_en":"Cheeks only, two nights a week.","optional":true}]'::jsonb, 15),
  ('6f1ac7fd-51e4-719b-2190-fe6efabdf276'::uuid, 'face-women-dry-am-eu', 'face', 'Πρωινή ρουτίνα για γυναίκες, ξηρή επιδερμίδα — ευρωπαϊκό μίνιμαλ', 'Women’s morning routine, dry skin — European minimal', 'women', 'dry', 'eu', 'am', 'Νερό και λιπίδια πριν από οτιδήποτε άλλο, και αντηλιακό υψηλής προστασίας που ταυτόχρονα ενυδατώνει. Το μακιγιάζ κάθεται καλύτερα σε δέρμα που δεν «τραβάει».', 'Water and lipids before anything else, and a high-protection sunscreen that also moisturises. Make-up sits better on skin that is not tight.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ή μόνο χλιαρό νερό.","note_en":"Or lukewarm water alone.","optional":true},{"order":2,"product_type_slug":"serum-hyaluronic-acid","note_el":"Σε νωπό δέρμα, πάντα με κρέμα από πάνω.","note_en":"On damp skin, always with a cream on top.","optional":false},{"order":3,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Μέχρι τον λαιμό και το ντεκολτέ.","note_en":"Down to the neck and chest.","optional":false},{"order":4,"product_type_slug":"sunscreen-eu-modern-filters","note_el":"Οι ενυδατικές εκδοχές «για ξηρή επιδερμίδα» λειτουργούν και ως βάση.","note_en":"The moisturising “dry skin” versions double as a primer.","optional":false},{"order":5,"product_type_slug":"lip-balm-spf","note_el":"Πριν το κραγιόν.","note_en":"Before lipstick.","optional":true}]'::jsonb, 6),
  ('0827cca1-84e3-6859-4997-3f57a83986a5'::uuid, 'face-women-dry-pm-kr', 'face', 'Βραδινή ρουτίνα για γυναίκες, ξηρή επιδερμίδα — κορεατικές στρώσεις', 'Women’s evening routine, dry skin — Korean layering', 'women', 'dry', 'kr', 'pm', 'Η πλήρης κορεατική εμπειρία για ξηρή επιδερμίδα: διπλός καθαρισμός, τόνερ σε στρώσεις, essence, ορός σαλιγκαριού, κρέμα και, δύο-τρεις νύχτες την εβδομάδα, μάσκα ύπνου.', 'The full Korean experience for dry skin: double cleanse, layered toner, essence, snail serum, cream and, two or three nights a week, a sleeping mask.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Διαλύει μακιγιάζ και αντηλιακό χωρίς τρίψιμο.","note_en":"Dissolves make-up and sunscreen without rubbing.","optional":false},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Δεύτερος καθαρισμός.","note_en":"Second cleanse.","optional":false},{"order":3,"product_type_slug":"toner-hydrating","note_el":"Τρεις στρώσεις — η «μέθοδος 7 στρώσεων» σε λογική εκδοχή.","note_en":"Three layers — the “7-skin method”, within reason.","optional":false},{"order":4,"product_type_slug":"essence-hydrating","note_el":"Πίεσε, μην τρίβεις.","note_en":"Press, do not rub.","optional":true},{"order":5,"product_type_slug":"serum-snail-mucin","note_el":"Ενυδάτωση και επούλωση μικροσημαδιών.","note_en":"Hydration and healing of small marks.","optional":false},{"order":6,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Σφράγισμα.","note_en":"Seal.","optional":false},{"order":7,"product_type_slug":"mask-sleeping-overnight","note_el":"2–3 νύχτες την εβδομάδα στη θέση της κρέμας.","note_en":"Two or three nights a week instead of the cream.","optional":true}]'::jsonb, 15),
  ('a433f2cb-c150-98c1-f0e9-09c73def168c'::uuid, 'face-women-normal-am-kr', 'face', 'Πρωινή ρουτίνα για γυναίκες, κανονική επιδερμίδα — κορεατικό στιλ', 'Women’s morning routine, normal skin — Korean style', 'women', 'normal', 'kr', 'am', 'Η πρωινή κορεατική ρουτίνα είναι πιο σύντομη από τη βραδινή: καθαρισμός, υδατικές στρώσεις, προαιρετικά βιταμίνη C, γαλάκτωμα και αντηλιακό PA++++. Όλα ελαφριά, για να κάθεται καλά και το μακιγιάζ.', 'The Korean morning routine is shorter than the evening one: cleanse, watery layers, optional vitamin C, emulsion and a PA++++ sunscreen. All light, so make-up sits well on top.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Ή μόνο νερό αν το δέρμα είναι ήρεμο το πρωί.","note_en":"Or water alone if your skin is calm in the morning.","optional":false},{"order":2,"product_type_slug":"toner-hydrating","note_el":"Δύο λεπτές στρώσεις.","note_en":"Two thin layers.","optional":false},{"order":3,"product_type_slug":"essence-hydrating","note_el":"Πίεσε με τις παλάμες, μην τρίβεις.","note_en":"Press in with your palms, do not rub.","optional":true},{"order":4,"product_type_slug":"serum-vitamin-c","note_el":"Το πρωινό αντιοξειδωτικό κάτω από το αντηλιακό.","note_en":"The morning antioxidant under your sunscreen.","optional":true},{"order":5,"product_type_slug":"moisturizer-emulsion-light","note_el":"Περίμενε ένα λεπτό πριν το αντηλιακό.","note_en":"Wait a minute before the sunscreen.","optional":false},{"order":6,"product_type_slug":"sunscreen-kr-pa-plus","note_el":"Δύο δάχτυλα ποσότητα· η ελαφριά υφή ξεγελά.","note_en":"Two finger-lengths; the light texture is deceptive.","optional":false}]'::jsonb, 8),
  ('ed628a92-74ab-8741-f17e-4dd9f73e1285'::uuid, 'face-women-normal-pm-jp', 'face', 'Βραδινή ρουτίνα για γυναίκες, κανονική επιδερμίδα — ιαπωνικό στιλ', 'Women’s evening routine, normal skin — Japanese style', 'women', 'normal', 'jp', 'pm', 'Διπλός καθαρισμός, μία φορά την εβδομάδα ενζυμική σκόνη, μια «πρώτη essence» με ζυμωμένα εκχυλίσματα και ελαφριές ενυδατικές στρώσεις. Η ιαπωνική ρουτίνα κυνηγά υφή και λάμψη, όχι πολλά βήματα.', 'A double cleanse, an enzyme powder once a week, a fermented “first essence” and light hydrating layers. The Japanese routine chases texture and glow, not step count.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Σε στεγνό πρόσωπο, μετά γαλακτωματοποίησε με λίγο νερό.","note_en":"On a dry face, then emulsify with a little water.","optional":false},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Δεύτερος καθαρισμός.","note_en":"Second cleanse.","optional":false},{"order":3,"product_type_slug":"exfoliant-enzyme-powder","note_el":"Μία φορά την εβδομάδα στη θέση του δεύτερου καθαρισμού.","note_en":"Once a week in place of the second cleanse.","optional":true},{"order":4,"product_type_slug":"essence-first-treatment","note_el":"Λίγες σταγόνες, ταμπονάρισμα με τις παλάμες.","note_en":"A few drops, patted in with your palms.","optional":true},{"order":5,"product_type_slug":"serum-hyaluronic-acid","note_el":"Όσο το δέρμα είναι ακόμη νωπό.","note_en":"While the skin is still damp.","optional":false},{"order":6,"product_type_slug":"moisturizer-emulsion-light","note_el":"Κρέμα από πάνω τον χειμώνα.","note_en":"Add a cream on top in winter.","optional":false}]'::jsonb, 12),
  ('b78241c3-8b11-151b-9b6c-578ae99d6a72'::uuid, 'face-women-oily-am-us', 'face', 'Πρωινή ρουτίνα για γυναίκες, λιπαρή επιδερμίδα — αμερικανικά «ενεργά»', 'Women’s morning routine, oily skin — US actives', 'women', 'oily', 'us', 'am', 'Καθαρισμός, βιταμίνη C ή νιασιναμίδη, ενυδάτωση χωρίς έλαια και ορυκτό αντηλιακό με ματ φινίρισμα — μια βάση που κρατά το μακιγιάζ στη θέση του ως το μεσημέρι.', 'Cleanse, vitamin C or niacinamide, oil-free hydration and a matte mineral sunscreen — a base that keeps make-up in place until midday.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Χλιαρό νερό· το ζεστό αυξάνει το σμήγμα.","note_en":"Lukewarm water; hot water drives sebum up.","optional":false},{"order":2,"product_type_slug":"serum-vitamin-c","note_el":"Εναλλακτικά νιασιναμίδη αν η C τσούζει.","note_en":"Or niacinamide if vitamin C stings.","optional":true},{"order":3,"product_type_slug":"serum-niacinamide","note_el":"Ρυθμίζει τη γυαλάδα και τους πόρους.","note_en":"Regulates shine and pores.","optional":false},{"order":4,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Λεπτή στρώση.","note_en":"A thin layer.","optional":false},{"order":5,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Με οξείδια σιδήρου (tinted) αν έχεις και κηλίδες.","note_en":"With iron oxides (tinted) if you also have dark spots.","optional":false}]'::jsonb, 6),
  ('6d24b582-44db-24d5-c59e-dc9155862da1'::uuid, 'face-women-oily-pm-us', 'face', 'Βραδινή ρουτίνα για γυναίκες, λιπαρή επιδερμίδα — αμερικανικά «ενεργά»', 'Women’s evening routine, oily skin — US actives', 'women', 'oily', 'us', 'pm', 'Το βράδυ της λιπαρής επιδερμίδας εναλλάσσει BHA και ρετινόλη, ποτέ την ίδια νύχτα. Ενυδάτωση κάθε φορά, και ένα υδροκολλοειδές επίθεμα για το σπυράκι που ήθελες να πειράξεις.', 'Oily skin’s evening alternates BHA and retinol, never on the same night. Moisturiser every time, and a hydrocolloid patch for the spot you were about to pick.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Με μακιγιάζ: πρώτα βάλσαμο καθαρισμού ή μικυλλιακό.","note_en":"With make-up on: a cleansing balm or micellar water first.","optional":false},{"order":2,"product_type_slug":"exfoliant-bha-salicylic","note_el":"Τρία βράδια την εβδομάδα.","note_en":"Three evenings a week.","optional":true},{"order":3,"product_type_slug":"serum-retinol","note_el":"Τα άλλα τρία βράδια· ξεκίνα με χαμηλή συγκέντρωση.","note_en":"The other three evenings; start with a low strength.","optional":false},{"order":4,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Ή κρέμα με κεραμίδια αν η ρετινόλη ξηραίνει.","note_en":"Or a ceramide cream if retinol is drying you out.","optional":false},{"order":5,"product_type_slug":"treatment-hydrocolloid-patch","note_el":"Τελευταίο, σε καθαρό στεγνό δέρμα.","note_en":"Last, on clean dry skin.","optional":true}]'::jsonb, 8),
  ('cabdb1ed-8ae0-a087-a153-6e8f35ba8cb6'::uuid, 'face-women-sensitive-am-jp', 'face', 'Πρωινή ρουτίνα για γυναίκες, ευαίσθητη επιδερμίδα — ιαπωνικό στιλ', 'Women’s morning routine, sensitive skin — Japanese style', 'women', 'sensitive', 'jp', 'am', 'Λίγα, ήπια, χωρίς άρωμα: η ιαπωνική αγορά έχει ολόκληρες σειρές «για ευαίσθητη επιδερμίδα» με ελάχιστα συστατικά. Το αντηλιακό εδώ είναι ορυκτό — τα υδαρή gel με οινόπνευμα τσούζουν.', 'Few, gentle, fragrance-free: the Japanese market has entire “sensitive skin” lines with minimal ingredients. The sunscreen here is mineral — the alcohol-based watery gels sting.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ή μόνο νερό το πρωί.","note_en":"Or water alone in the morning.","optional":true},{"order":2,"product_type_slug":"toner-hydrating","note_el":"Χωρίς οινόπνευμα, χωρίς άρωμα.","note_en":"Alcohol-free, fragrance-free.","optional":false},{"order":3,"product_type_slug":"moisturizer-emulsion-light","note_el":"Ή κρέμα με κεραμίδια αν έχεις ξεφλούδισμα.","note_en":"Or a ceramide cream if you are flaking.","optional":false},{"order":4,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Οξείδιο ψευδαργύρου: καταπραΰνει κιόλας.","note_en":"Zinc oxide: it soothes as well.","optional":false}]'::jsonb, 5),
  ('14e68576-0521-f34f-c587-db23bd5677ee'::uuid, 'face-women-sensitive-pm-eu', 'face', 'Βραδινή ρουτίνα για γυναίκες, ευαίσθητη επιδερμίδα — ευρωπαϊκό δερμοκαλλυντικό', 'Women’s evening routine, sensitive skin — European dermo-cosmetic', 'women', 'sensitive', 'eu', 'pm', 'Αφαίρεση μακιγιάζ χωρίς τρίψιμο, ήπιος καθαρισμός, αζελαϊκό οξύ για κοκκινίλα και σπυράκια (ασφαλές και στην εγκυμοσύνη) και κρέμα φραγμού. Τέσσερα βήματα, όλα από το φαρμακείο.', 'Make-up removal without rubbing, a gentle cleanse, azelaic acid for redness and spots (safe in pregnancy too) and a barrier cream. Four steps, all from the pharmacy.', '[{"order":1,"product_type_slug":"cleanser-micellar-water","note_el":"Με βαμβάκι, χωρίς πίεση· ξέβγαλε μετά.","note_en":"On a cotton pad, no pressure; rinse afterwards.","optional":true},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Χλιαρό νερό.","note_en":"Lukewarm water.","optional":false},{"order":3,"product_type_slug":"serum-azelaic-acid","note_el":"Ένα ελαφρύ τσούξιμο τις πρώτες μέρες είναι φυσιολογικό.","note_en":"A light tingle in the first days is normal.","optional":false},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Χωρίς άρωμα, γενναιόδωρα.","note_en":"Fragrance-free, generously.","optional":false}]'::jsonb, 7),
  ('548dd72c-ab32-1ea8-c428-5668760e2611'::uuid, 'nails-all-brittle-strengthening', 'nails', 'Πρόγραμμα 4 εβδομάδων για εύθραυστα νύχια', 'Four-week programme for brittle nails', 'all', 'all', 'global', 'pm', 'Τα νύχια μεγαλώνουν περίπου 3 χιλιοστά τον μήνα, οπότε χρειάζονται εβδομάδες για να δεις αλλαγή. Κάθε βράδυ: λάδι, ενισχυτική θεραπεία δύο φορές την εβδομάδα, κρέμα· λιμάρισμα μία φορά την εβδομάδα. Αν τα νύχια αλλάζουν χρώμα ή σχήμα, δες γιατρό.', 'Nails grow about 3 mm a month, so it takes weeks to see a change. Every night: oil, a strengthener twice a week, cream; filing once a week. If nails change colour or shape, see a doctor.', '[{"order":1,"product_type_slug":"nail-file-glass","note_el":"Μία φορά την εβδομάδα, κοντά, για να μη «σκαλώνουν».","note_en":"Once a week, short, so they do not catch.","optional":true},{"order":2,"product_type_slug":"cuticle-oil-jojoba","note_el":"Κάθε βράδυ, σε νύχι και επωνύχια.","note_en":"Every night, on nail and cuticles.","optional":false},{"order":3,"product_type_slug":"nail-treatment-strengthener-keratin","note_el":"Δύο βράδια την εβδομάδα, μία στρώση· αφαίρεση και ξανά κάθε εβδομάδα.","note_en":"Two nights a week, one coat; remove and redo weekly.","optional":false},{"order":4,"product_type_slug":"hand-cream-urea","note_el":"Γάντια για τα πιάτα όλες τις 4 εβδομάδες.","note_en":"Gloves for the dishes throughout the four weeks.","optional":false}]'::jsonb, 5),
  ('ea00625e-6139-90ed-1b0b-f125f3c978ae'::uuid, 'nails-all-post-gel-recovery', 'nails', 'Ανάκαμψη μετά από gel ή ακρυλικό', 'Recovery after gel or acrylic', 'all', 'all', 'global', 'pm', 'Μετά την αφαίρεση gel ή ακρυλικού η πλάκα είναι λεπτή και αφυδατωμένη. Για δύο-τρεις εβδομάδες: τίποτα πάνω στο νύχι εκτός από λάδι και, προαιρετικά, μια ενισχυτική θεραπεία. Μη ξύνεις ποτέ υπολείμματα — μαλάκωσέ τα.', 'After gel or acrylic removal the plate is thin and dehydrated. For two or three weeks: nothing on the nail but oil and, optionally, a strengthener. Never scrape off residue — soften it.', '[{"order":1,"product_type_slug":"nail-remover-acetone-free","note_el":"Μόνο για τα τελευταία ίχνη· το gel το ίδιο χρειάζεται ασετόν ή σαλόνι.","note_en":"Only for the last traces; the gel itself needs acetone or the salon.","optional":true},{"order":2,"product_type_slug":"nail-file-glass","note_el":"Κόντυνε τα νύχια — το μακρύ αδύναμο νύχι σπάει βαθιά.","note_en":"Shorten the nails — a long weak nail breaks deep.","optional":true},{"order":3,"product_type_slug":"cuticle-oil-jojoba","note_el":"Δύο φορές τη μέρα για τρεις εβδομάδες.","note_en":"Twice a day for three weeks.","optional":false},{"order":4,"product_type_slug":"nail-treatment-strengthener-keratin","note_el":"Από τη δεύτερη εβδομάδα, αν ξεφλουδίζουν στις άκρες.","note_en":"From the second week, if the tips are peeling.","optional":true},{"order":5,"product_type_slug":"hand-cream-urea","note_el":"Κάθε βράδυ, μέχρι τα επωνύχια.","note_en":"Every night, up to the cuticles.","optional":false}]'::jsonb, 5),
  ('055e09f0-5537-021b-f106-68442848436e'::uuid, 'nails-men-weekly-clean', 'nails', 'Εβδομαδιαία περιποίηση νυχιών για άντρες — κοντά και καθαρά', 'Men’s weekly nail care — short and clean', 'men', 'all', 'global', 'weekly', 'Δέκα λεπτά την Κυριακή: μαλάκωμα επωνυχίων, λιμάρισμα κοντά προς μία κατεύθυνση, προαιρετικό γυάλισμα και κρέμα χεριών. Χωρίς βερνίκι, χωρίς κόψιμο επωνυχίων, χωρίς ψαλίδι στα δάχτυλα.', 'Ten minutes on a Sunday: soften the cuticles, file short in one direction, optional buffing and hand cream. No polish, no cutting cuticles, no scissors on your fingers.', '[{"order":1,"product_type_slug":"cuticle-oil-jojoba","note_el":"Μασάζ στη βάση κάθε νυχιού· σπρώξε απαλά τα επωνύχια με πετσέτα μετά το ντους.","note_en":"Massage into each nail base; gently push the cuticles back with a towel after the shower.","optional":false},{"order":2,"product_type_slug":"nail-file-glass","note_el":"Κοντά, ίσια με ελαφρά στρογγυλεμένες γωνίες, προς μία κατεύθυνση.","note_en":"Short, straight across with slightly rounded corners, in one direction.","optional":false},{"order":3,"product_type_slug":"nail-file-buffer-block","note_el":"Μία φορά τον μήνα, ελαφρά, για φυσική γυαλάδα.","note_en":"Once a month, lightly, for a natural shine.","optional":true},{"order":4,"product_type_slug":"hand-cream-urea","note_el":"Μέχρι τα επωνύχια· ξανά μετά από κάθε πλύσιμο πιάτων.","note_en":"Right up to the cuticles; again after every round of dish-washing.","optional":false}]'::jsonb, 10),
  ('0a8c46a4-0480-9556-fe37-2139f14ca696'::uuid, 'nails-women-weekly-maintenance', 'nails', 'Εβδομαδιαία συντήρηση ανάμεσα σε μανικιούρ', 'Weekly upkeep between manicures', 'women', 'all', 'global', 'weekly', 'Για τις εβδομάδες χωρίς σαλόνι: αφαίρεση βερνικιού χωρίς ασετόν, σχήμα με γυάλινη λίμα, λάδι επωνυχίων, μια βάση που αφήνει το νύχι να «αναπνεύσει» και κρέμα χεριών.', 'For the weeks away from the salon: acetone-free removal, shaping with a glass file, cuticle oil, a base coat that lets the nail breathe and hand cream.', '[{"order":1,"product_type_slug":"nail-remover-acetone-free","note_el":"Κράτα το βαμβάκι λίγα δευτερόλεπτα πάνω στο νύχι αντί να τρίβεις.","note_en":"Hold the pad on the nail for a few seconds instead of rubbing.","optional":false},{"order":2,"product_type_slug":"nail-file-glass","note_el":"Σχήμα που ακολουθεί τη βάση του νυχιού· όχι μύτες σε αδύναμα νύχια.","note_en":"A shape that follows the nail base; no points on weak nails.","optional":false},{"order":3,"product_type_slug":"cuticle-oil-jojoba","note_el":"Μασάζ, μετά σπρώξε απαλά — ποτέ κόψιμο.","note_en":"Massage, then push back gently — never cut.","optional":false},{"order":4,"product_type_slug":"base-coat-breathable","note_el":"Μία στρώση, με ή χωρίς χρώμα από πάνω.","note_en":"One coat, with or without colour on top.","optional":true},{"order":5,"product_type_slug":"hand-cream-urea","note_el":"Κάθε βράδυ πριν τον ύπνο.","note_en":"Every night before bed.","optional":false}]'::jsonb, 15)
insert into hygieia.skincare_tips (id, slug, area, title_el, title_en, body_el, body_en, audiences, skin_types, concerns, regions, sources, needs_source) values
  ('61621fea-f561-d3aa-0e20-887fa5ee7b29'::uuid, 'face-all-check-sunscreen-expiry-and-storage', 'face', 'Το περσινό αντηλιακό από το αυτοκίνητο δεν μετράει', 'Last year’s sunscreen from the car does not count', 'Τα φίλτρα διασπώνται με τη ζέστη: ένα μπουκάλι που πέρασε το καλοκαίρι στο ντουλαπάκι του αυτοκινήτου ή στην άμμο έχει πιθανότατα χάσει μέρος της προστασίας του. Κοίτα την ημερομηνία λήξης ή το σύμβολο «ανοιχτού βάζου» (π.χ. 12M) και πέταξε ό,τι έχει αλλάξει μυρωδιά ή υφή. Ένα αντηλιακό που χρησιμοποιείται σωστά τελειώνει μέσα σε μία σεζόν ούτως ή άλλως.', 'Filters break down in heat: a bottle that spent the summer in the glove box or on the sand has probably lost part of its protection. Check the expiry date or the open-jar symbol (e.g. 12M) and bin anything whose smell or texture has changed. A sunscreen used properly runs out within a season anyway.', array['all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.mayoclinic.org/healthy-lifestyle/adult-health/in-depth/best-sunscreen/art-20045110']::text[], false),
  ('ed94d082-d930-d497-234f-852e94e2c1a6'::uuid, 'face-all-check-your-moles-abcde', 'face', 'Κοίτα τις ελιές σου μία φορά τον μήνα: το ABCDE', 'Check your moles once a month: the ABCDE rule', 'Ασυμμετρία, ακανόνιστα όρια, πολλά χρώματα, διάμετρος πάνω από 6 χιλιοστά και κάθε αλλαγή σε μέγεθος, σχήμα ή αίσθηση είναι τα σημάδια που θέλουν άμεση εξέταση. Ο μεσογειακός ήλιος μαζί με τα ανοιχτόχρωμα δέρματα κάνει τον έλεγχο απαραίτητο, όχι πολυτέλεια. Μια ετήσια χαρτογράφηση στον δερματολόγο είναι η καλύτερη πρόληψη για όποιον έχει πολλές ελιές ή οικογενειακό ιστορικό.', 'Asymmetry, irregular borders, several colours, a diameter over 6 mm and any change in size, shape or sensation are the signs that need prompt examination. The Mediterranean sun combined with fair skin makes checking a necessity, not a luxury. A yearly mole map at the dermatologist is the best prevention for anyone with many moles or a family history.', array['all']::text[], array['all']::text[], array['sun','general']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/melanoma-skin-cancer/symptoms/']::text[], false),
  ('73ab919d-eb58-ebb8-649b-c496f63f71b8'::uuid, 'face-all-do-not-pop-pimples', 'face', 'Μην πιέζεις τα σπυράκια', 'Do not pop pimples', 'Το ζούληγμα σπρώχνει βακτήρια και σμήγμα βαθύτερα, μεγαλώνει τη φλεγμονή και είναι η πρώτη αιτία για σημάδια και ουλές που μένουν μήνες. Ένα υδροκολλοειδές επίθεμα πάνω στο σπυράκι το προστατεύει από τα χέρια σου και το αποφορτίζει μέσα σε μια νύχτα. Ακμή που αφήνει ουλές ή δεν βελτιώνεται σε 2–3 μήνες με προϊόντα του φαρμακείου χρειάζεται δερματολόγο.', 'Squeezing pushes bacteria and sebum deeper, enlarges the inflammation and is the main cause of marks and scars that last for months. A hydrocolloid patch over the spot keeps your fingers off it and drains it overnight. Acne that scars or does not improve within two or three months of pharmacy products needs a dermatologist.', array['all']::text[], array['oily','combination','all']::text[], array['acne']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/acne/','https://www.aad.org/public/diseases/acne/skin-care/tips']::text[], false),
  ('bf1dbc85-4383-b8d6-cf19-9a7b2ca33c99'::uuid, 'face-all-eu-labels-inci-and-claims', 'face', 'Πώς διαβάζεις μια ευρωπαϊκή ετικέτα καλλυντικού', 'How to read a European cosmetics label', 'Στην ΕΕ τα συστατικά γράφονται με τις διεθνείς ονομασίες INCI, σε φθίνουσα σειρά ποσότητας μέχρι το 1 % — ό,τι είναι στις πρώτες πέντε θέσεις είναι το προϊόν. Οι όροι «υποαλλεργικό», «δερματολογικά ελεγμένο» και «φυσικό» δεν έχουν νομικό ορισμό ούτε έγκριση. Το σύμβολο του ανοιχτού βάζου (π.χ. 12M) λέει πόσους μήνες κρατά αφού το ανοίξεις.', 'In the EU ingredients are listed by their international INCI names in descending order of amount down to 1 % — whatever sits in the first five places is the product. “Hypoallergenic”, “dermatologically tested” and “natural” have no legal definition or approval. The open-jar symbol (e.g. 12M) tells you how many months it keeps once opened.', array['all']::text[], array['all']::text[], array['general']::text[], array['eu']::text[], array['https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32009R1223']::text[], false),
  ('733a648a-8d22-d35c-9a64-e8c487cb2e98'::uuid, 'face-all-exfoliate-at-most-two-or-three-times-a-week', 'face', 'Απολέπιση το πολύ δύο-τρεις φορές την εβδομάδα', 'Exfoliate at most two or three times a week', 'Η επιδερμίδα ανανεώνεται μόνη της κάθε τέσσερις περίπου εβδομάδες· η απολέπιση απλώς βοηθά. Καθημερινά οξέα ή scrub αφαιρούν και τα υγιή κύτταρα, και το αποτέλεσμα είναι γυαλάδα, τσούξιμο και κοκκινίλα που μοιάζουν με «ευαίσθητη επιδερμίδα». Αν το δέρμα σου τσούζει με απλή ενυδατική, κάνε παύση από κάθε απολέπιση για δύο εβδομάδες.', 'Skin renews itself roughly every four weeks; exfoliation merely helps. Daily acids or scrubs remove healthy cells too, and the result is shine, stinging and redness that passes for “sensitive skin”. If plain moisturiser stings, pause all exfoliation for two weeks.', array['all']::text[], array['all']::text[], array['texture','redness']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home']::text[], false),
  ('7cd2d366-7353-6b0c-4daa-ad1cf025be7c'::uuid, 'face-all-fragrance-free-for-reactive-skin', 'face', 'Ευαίσθητη επιδερμίδα: χωρίς άρωμα, χωρίς αιθέρια έλαια', 'Reactive skin: fragrance-free, no essential oils', 'Το άρωμα είναι η συχνότερη αιτία αλλεργίας επαφής από καλλυντικά, και τα «φυσικά» αιθέρια έλαια (λεβάντα, τσάι, εσπεριδοειδή) δεν αποτελούν εξαίρεση. «Χωρίς άρωμα» (fragrance-free) σημαίνει τίποτα· «άοσμο» (unscented) μπορεί να σημαίνει άρωμα που καλύπτει άλλη μυρωδιά. Στην ΕΕ τα 26 πιο συχνά αλλεργιογόνα αρώματα αναγράφονται υποχρεωτικά στα συστατικά — ψάξε για linalool, limonene, geraniol.', 'Fragrance is the most common cause of contact allergy from cosmetics, and “natural” essential oils (lavender, tea tree, citrus) are no exception. “Fragrance-free” means none; “unscented” may mean a fragrance masking another smell. In the EU the 26 most common fragrance allergens must be listed in the ingredients — look for linalool, limonene, geraniol.', array['all']::text[], array['sensitive']::text[], array['redness','general']::text[], array['eu','global']::text[], array['https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32009R1223']::text[], false),
  ('1ccce815-7742-52b2-7379-04890bbb90ff'::uuid, 'face-all-greek-summer-humidity-lighter-textures', 'face', 'Ελληνικό καλοκαίρι: ελαφρύτερες υφές, ίδια βήματα', 'Greek summer: lighter textures, same steps', 'Με 35 βαθμούς και υγρασία η κρέμα του χειμώνα γίνεται λιπαρό φιλμ που φράζει πόρους. Μην κόψεις την ενυδάτωση — άλλαξε την υφή: gel ή γαλάκτωμα αντί για κρέμα, υδατικός ορός αντί για έλαιο, και αντηλιακό ελαφρύ που θα βάλεις πραγματικά σε αρκετή ποσότητα. Ο ιδρώτας δεν ενυδατώνει· αντίθετα, το αλάτι του ξηραίνει.', 'At 35 degrees with humidity, your winter cream turns into a greasy film that clogs pores. Do not drop the moisture — change the texture: gel or emulsion instead of cream, a watery serum instead of oil, and a light sunscreen you will actually apply in a full dose. Sweat does not hydrate; its salt dries you out.', array['all']::text[], array['oily','combination','all']::text[], array['hydration','pores','sun']::text[], array['eu','global']::text[], '{}'::text[], true),
  ('77bfb90f-48a8-a43e-dfea-c221238a43f9'::uuid, 'face-all-japanese-gel-sunscreens-may-sting', 'face', 'Τα ιαπωνικά υδαρή αντηλιακά: υπέροχη υφή, συχνά με οινόπνευμα', 'Japanese watery sunscreens: lovely texture, often with alcohol', 'Οι σχεδόν υδάτινες υφές από την Ιαπωνία είναι ιδανικές για λιπαρή επιδερμίδα και για όσους μισούν την αίσθηση του αντηλιακού. Η δροσιά όμως συχνά έρχεται από οινόπνευμα, που σε ξηρή ή ευαίσθητη επιδερμίδα τσούζει και ξηραίνει. Αν τσούζει, γύρνα σε κορεατική υφή με centella ή σε ευρωπαϊκή ενυδατική εκδοχή.', 'The near-watery textures from Japan are ideal for oily skin and for anyone who hates the feel of sunscreen. The cooling sensation, though, often comes from alcohol, which stings and dries on dry or sensitive skin. If it stings, switch to a Korean texture with centella or a European moisturising version.', array['all']::text[], array['dry','sensitive']::text[], array['sun','redness']::text[], array['jp','kr','eu']::text[], '{}'::text[], true),
  ('a402f72e-1f87-8bde-6b67-be0f9a9f7038'::uuid, 'face-all-korean-layering-thin-to-thick', 'face', 'Κορεατικές στρώσεις: από το πιο αραιό στο πιο πυκνό', 'Korean layering: thinnest to thickest', 'Ο κανόνας της κορεατικής ρουτίνας είναι απλός: τόνερ, essence, ορός, γαλάκτωμα, κρέμα — κάθε προϊόν πιο πυκνό από το προηγούμενο, κάθε στρώση πάνω σε ελαφρώς νωπό δέρμα. Το «χτύπημα» με τις παλάμες αντί για τρίψιμο βοηθά την απορρόφηση και δεν τραβά το δέρμα. Δεν χρειάζονται δέκα βήματα: τρεις σωστές στρώσεις κάνουν τη διαφορά.', 'The Korean rule is simple: toner, essence, serum, emulsion, cream — each product thicker than the last, each layer on slightly damp skin. Patting with your palms instead of rubbing helps absorption and does not tug the skin. You do not need ten steps: three well-chosen layers make the difference.', array['all']::text[], array['all']::text[], array['hydration','general']::text[], array['kr']::text[], '{}'::text[], true),
  ('7509b8c6-b297-6852-d54e-f9b46626a619'::uuid, 'face-all-lukewarm-water-short-showers', 'face', 'Χλιαρό νερό και σύντομο ντους', 'Lukewarm water and short showers', 'Το καυτό νερό διαλύει τα λιπίδια του δέρματος όπως διαλύει το λίπος στα πιάτα, και μετά το δέρμα «τραβάει» και ξεφλουδίζει. Πέντε ως δέκα λεπτά με χλιαρό νερό αρκούν, και η ενυδατική μπαίνει μέσα σε τρία λεπτά από το ντους, όσο το δέρμα είναι ακόμη νωπό. Το πρόσωπο δεν χρειάζεται να πλένεται κάτω από τη ροή του ντους.', 'Hot water dissolves the skin’s lipids the way it dissolves grease on dishes, and afterwards the skin feels tight and flakes. Five to ten minutes of lukewarm water is enough, and moisturiser goes on within three minutes of the shower while the skin is still damp. Your face does not need to be washed under the shower stream.', array['all']::text[], array['dry','sensitive','all']::text[], array['hydration','redness']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin','https://www.mayoclinic.org/diseases-conditions/dry-skin/symptoms-causes/syc-20353885']::text[], false),
  ('feaef8cc-0931-4ec4-5f86-8281fd94e776'::uuid, 'face-all-mediterranean-sun-is-strong-from-april', 'face', 'Ο μεσογειακός ήλιος είναι δυνατός από τον Απρίλιο ως τον Οκτώβριο', 'The Mediterranean sun is strong from April to October', 'Στην Ελλάδα ο δείκτης UV ξεπερνά το 3 —το όριο πάνω από το οποίο χρειάζεται προστασία— σχεδόν κάθε μέρα από την άνοιξη ως το φθινόπωρο, και το καλοκαίρι φτάνει 9–11. Το κάψιμο τον Μάιο είναι τόσο συνηθισμένο γιατί το δέρμα βγαίνει από τον χειμώνα χωρίς μαύρισμα. Κοίτα τον δείκτη UV στην εφαρμογή καιρού όπως κοιτάς τη θερμοκρασία.', 'In Greece the UV index exceeds 3 — the threshold above which protection is needed — almost daily from spring to autumn, and reaches 9–11 in summer. May sunburns are so common because the skin comes out of winter with no tan. Check the UV index in your weather app the way you check the temperature.', array['all']::text[], array['all']::text[], array['sun']::text[], array['eu','global']::text[], array['https://www.who.int/news-room/questions-and-answers/item/radiation-sun-protection']::text[], false),
  ('5fb91f06-07dc-6723-2ee4-3a291e3ec525'::uuid, 'face-all-niacinamide-pairs-with-almost-everything', 'face', 'Η νιασιναμίδη συνδυάζεται με σχεδόν τα πάντα', 'Niacinamide pairs with almost everything', 'Ο παλιός μύθος ότι η νιασιναμίδη «ακυρώνει» τη βιταμίνη C προέρχεται από πειράματα σε υψηλή θερμοκρασία δεκαετιών πριν· στις σημερινές συνθέσεις συνυπάρχουν άνετα. Σε 2–5 % είναι το πιο ανεκτό «ενεργό» για αρχάριους, μαζί με ρετινόλη, οξέα ή αντηλιακό. Πάνω από 10 % μερικοί κοκκινίζουν — περισσότερο δεν σημαίνει καλύτερο.', 'The old myth that niacinamide “cancels” vitamin C comes from high-temperature experiments decades ago; in today’s formulas they coexist happily. At 2–5 % it is the best-tolerated active for beginners, alongside retinol, acids or sunscreen. Above 10 % some people flush — more is not better.', array['all']::text[], array['all']::text[], array['general','pores','redness']::text[], array['global']::text[], '{}'::text[], true),
  ('fe74ead1-e5cc-e889-f65c-aea443b82605'::uuid, 'face-all-oily-skin-still-needs-moisturiser', 'face', 'Και η λιπαρή επιδερμίδα θέλει ενυδατική', 'Oily skin needs moisturiser too', 'Το σμήγμα δεν είναι νερό: μια επιδερμίδα μπορεί να γυαλίζει και ταυτόχρονα να είναι αφυδατωμένη, ειδικά όταν της αφαιρείς τα λιπίδια με δυνατά καθαριστικά και οξέα. Όταν παραλείπεις την ενυδάτωση, πολλές επιδερμίδες απαντούν με περισσότερο σμήγμα. Διάλεξε gel χωρίς έλαια, «non-comedogenic», και βάλε λεπτή στρώση δύο φορές τη μέρα.', 'Sebum is not water: skin can shine and be dehydrated at the same time, especially when strong cleansers and acids strip its lipids. Skip the moisturiser and many skins answer with more sebum. Choose an oil-free, non-comedogenic gel and apply a thin layer twice a day.', array['all']::text[], array['oily','combination']::text[], array['hydration','acne','pores']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/acne/skin-care/tips']::text[], false),
  ('8e2fddd2-099f-0a1d-68e8-1e283e4f37fd'::uuid, 'face-all-one-active-per-evening', 'face', 'Ένα «ενεργό» κάθε βράδυ, όχι τρία', 'One active per evening, not three', 'Ρετινόλη, οξέα AHA/BHA, βιταμίνη C και υπεροξείδιο του βενζοϋλίου δουλεύουν όλα — αλλά όχι στην ίδια στρώση την ίδια βραδιά. Ο συνδυασμός τους ερεθίζει και συχνά αλληλοεξουδετερώνεται. Μοίρασέ τα: οξέα Δευτέρα-Τετάρτη-Παρασκευή, ρετινόλη Τρίτη-Πέμπτη-Σάββατο, βιταμίνη C το πρωί και μια βραδιά την εβδομάδα μόνο ενυδάτωση.', 'Retinol, AHA/BHA acids, vitamin C and benzoyl peroxide all work — but not in the same layer on the same night. Combining them irritates and often cancels out. Spread them: acids Monday-Wednesday-Friday, retinol Tuesday-Thursday-Saturday, vitamin C in the morning and one evening a week of moisturiser only.', array['all']::text[], array['all']::text[], array['texture','acne','aging']::text[], array['us','global']::text[], '{}'::text[], true),
  ('d6a86860-7308-966c-f736-547bbc809b13'::uuid, 'face-all-patch-test-every-new-product', 'face', 'Patch test σε κάθε νέο προϊόν — πίσω από το αυτί ή στο εσωτερικό του βραχίονα', 'Patch test every new product — behind the ear or on the inner arm', 'Βάλε λίγο προϊόν σε ένα σημείο στο μέγεθος νομίσματος πίσω από το αυτί ή στο εσωτερικό του πήχη, δύο φορές τη μέρα για 7–10 μέρες, και κοίτα για κοκκινίλα, φαγούρα ή σπυράκια. Οι αλλεργίες επαφής αργούν να εμφανιστούν, γι’ αυτό μία μέρα δεν αρκεί. Ένα προϊόν τη φορά, αλλιώς δεν θα ξέρεις ποιο έφταιξε.', 'Apply a little product to a coin-sized spot behind the ear or on the inner forearm, twice a day for 7–10 days, and watch for redness, itching or bumps. Contact allergies take time to show, so one day is not enough. One new product at a time, or you will not know which one was to blame.', array['all']::text[], array['sensitive','all']::text[], array['redness','general']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-basics/care/how-to-test-skin-care-products']::text[], false),
  ('2f9fd4df-703e-8beb-b04c-49e866288b08'::uuid, 'face-all-pillowcase-phone-and-hands', 'face', 'Μαξιλαροθήκη, κινητό και χέρια: οι αθόρυβοι ένοχοι', 'Pillowcase, phone and hands: the quiet culprits', 'Η μαξιλαροθήκη μαζεύει σμήγμα, προϊόντα μαλλιών και ιδρώτα και τα επιστρέφει στο μάγουλό σου οκτώ ώρες τη νύχτα· άλλαξέ τη μία-δύο φορές την εβδομάδα. Η οθόνη του κινητού ακουμπά στο ίδιο μάγουλο όλη μέρα — σκούπισέ τη με μαντιλάκι. Και τα χέρια μακριά από το πρόσωπο, ειδικά στο γραφείο.', 'Your pillowcase collects sebum, hair products and sweat and hands them back to your cheek for eight hours a night; change it once or twice a week. Your phone screen rests on that same cheek all day — wipe it with a cleansing wipe. And keep your hands off your face, especially at a desk.', array['all']::text[], array['oily','combination','all']::text[], array['acne']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/acne/skin-care/tips']::text[], false),
  ('b6495ece-8c7b-3b45-9ceb-5747f8b030a3'::uuid, 'face-all-read-the-uva-circle-and-pa-grade', 'face', 'Διάβασε τον κύκλο UVA και τον δείκτη PA', 'Read the UVA circle and the PA grade', 'Το SPF μετρά μόνο την προστασία από το κάψιμο (UVB). Στην ΕΕ ο κύκλος με τα γράμματα «UVA» σημαίνει προστασία UVA τουλάχιστον το ένα τρίτο του SPF· στην Κορέα και την Ιαπωνία το ίδιο λέει ο δείκτης PA, με PA++++ το μέγιστο. Στις ΗΠΑ ψάξε τη λέξη «broad spectrum». Αντηλιακό χωρίς καμία από αυτές τις ενδείξεις προστατεύει μόνο από το κάψιμο, όχι από τη γήρανση και τις κηλίδες.', 'SPF measures only protection from burning (UVB). In the EU the circle with the letters “UVA” means UVA protection of at least one third of the SPF; in Korea and Japan the PA grade says the same, with PA++++ the maximum. In the US look for “broad spectrum”. A sunscreen with none of these marks protects against burning only, not ageing and spots.', array['all']::text[], array['all']::text[], array['sun','aging','pigmentation']::text[], array['eu','kr','jp','us']::text[], array['https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32006H0647']::text[], false),
  ('5548802d-a5b9-1006-b07c-ec4a982976c0'::uuid, 'face-all-reapply-every-two-hours-outdoors', 'face', 'Στον ήλιο, ξανά αντηλιακό κάθε δύο ώρες', 'In the sun, reapply every two hours', 'Κανένα αντηλιακό δεν κρατά όλη μέρα: ο ιδρώτας, το νερό, το σκούπισμα με την πετσέτα και το ίδιο το φως το καταναλώνουν. Έξω ξαναβάζεις κάθε δύο ώρες και αμέσως μετά το κολύμπι, ακόμη και με ετικέτα «water resistant». Στο γραφείο η πρωινή στρώση αρκεί — εκτός αν κάθεσαι δίπλα σε ηλιόλουστο παράθυρο.', 'No sunscreen lasts all day: sweat, water, towelling off and the light itself use it up. Outdoors you reapply every two hours and straight after swimming, even with a “water resistant” label. In the office the morning layer is enough — unless you sit beside a sunny window.', array['all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun']::text[], false),
  ('d1b4ce62-4240-84a3-ad65-38d3ff8398dc'::uuid, 'face-all-retinol-pea-on-dry-skin-sandwich', 'face', 'Ένα μπιζέλι ρετινόλη, σε στεγνό δέρμα, ανάμεσα σε δύο στρώσεις ενυδατικής', 'A pea of retinol, on dry skin, between two layers of moisturiser', 'Περισσότερη ρετινόλη δεν σημαίνει καλύτερο αποτέλεσμα — σημαίνει περισσότερο ερεθισμό. Μια ποσότητα όσο ένα μπιζέλι αρκεί για όλο το πρόσωπο, πάνω σε εντελώς στεγνό δέρμα, μακριά από τα βλέφαρα και τις γωνίες της μύτης. Αν ξηραίνεσαι εύκολα, βάλε ενυδατική πριν και μετά — το «σάντουιτς» μειώνει τον ερεθισμό χωρίς να ακυρώνει τη δράση.', 'More retinol does not mean better results — it means more irritation. A pea-sized amount covers the whole face, applied to fully dry skin, away from the eyelids and the corners of the nose. If you dry out easily, moisturise before and after — the “sandwich” cuts irritation without cancelling the effect.', array['all']::text[], array['dry','sensitive','all']::text[], array['aging','hydration']::text[], array['global']::text[], '{}'::text[], true),
  ('f498b7e5-25dd-bf0e-b5f3-dcec550a5a29'::uuid, 'face-all-retinol-start-slow-twice-a-week', 'face', 'Ρετινόλη: ξεκίνα δύο βράδια την εβδομάδα', 'Retinol: start two nights a week', 'Οι πρώτες εβδομάδες με ρετινόλη φέρνουν ξηρότητα και ξεφλούδισμα σε σχεδόν όλους — όχι επειδή «δουλεύει», αλλά επειδή το δέρμα προσαρμόζεται. Ξεκίνα με χαμηλή συγκέντρωση δύο βράδια την εβδομάδα και πρόσθεσε ένα βράδυ κάθε δύο εβδομάδες αν δεν ερεθίζεται. Ο στόχος είναι η συνέπεια επί μήνες, όχι η ένταση σε μία εβδομάδα.', 'The first weeks on retinol bring dryness and flaking for almost everyone — not because it is “working” but because the skin is adapting. Start with a low strength two nights a week and add a night every two weeks if there is no irritation. The goal is consistency over months, not intensity in one week.', array['all']::text[], array['all']::text[], array['aging','texture','acne']::text[], array['global']::text[], '{}'::text[], true),
  ('9df8a9bc-f673-f6bd-a06b-72527956c3b7'::uuid, 'face-all-rinse-off-salt-after-the-sea', 'face', 'Μετά τη θάλασσα, ξέπλυμα με γλυκό νερό', 'After the sea, rinse with fresh water', 'Το αλάτι που στεγνώνει πάνω στο δέρμα τραβά νερό από αυτό και αφήνει το πρόσωπο σφιχτό και τα μαλλιά σαν άχυρο. Ένα γρήγορο ξέπλυμα στο ντους της παραλίας, μετά ενυδατική και ξανά αντηλιακό αν μένεις στον ήλιο. Το χλώριο της πισίνας κάνει το ίδιο, με επιπλέον ερεθισμό στα μάτια και τον λαιμό.', 'Salt drying on the skin pulls water out of it and leaves the face tight and the hair like straw. A quick rinse at the beach shower, then moisturiser and sunscreen again if you are staying in the sun. Pool chlorine does the same, with extra irritation for eyes and neck.', array['all']::text[], array['all']::text[], array['hydration','sun']::text[], array['eu','global']::text[], '{}'::text[], true),
  ('2004946c-b3a9-1390-3bfd-644f046a7346'::uuid, 'face-all-rosacea-know-your-triggers', 'face', 'Ροδόχρους ακμή: μάθε τι την πυροδοτεί', 'Rosacea: learn your triggers', 'Κοκκινίλα στα μάγουλα και τη μύτη που φουντώνει με ήλιο, ζέστη, κρασί, καυτερά, ζεστά ροφήματα ή άγχος είναι συχνά ροδόχρους ακμή — όχι «ευαίσθητο δέρμα» και όχι κανονική ακμή. Κράτα ημερολόγιο δύο εβδομάδων για να βρεις τους δικούς σου διεγέρτες, προτίμησε ορυκτό αντηλιακό και αζελαϊκό οξύ και απόφυγε scrub και οινόπνευμα. Είναι χρόνια αλλά ελέγχεται· ο δερματολόγος έχει αγωγές που μειώνουν τα επεισόδια.', 'Redness on cheeks and nose that flares with sun, heat, wine, spicy food, hot drinks or stress is often rosacea — not “sensitive skin” and not ordinary acne. Keep a two-week diary to find your own triggers, prefer mineral sunscreen and azelaic acid and avoid scrubs and alcohol. It is chronic but controllable; a dermatologist has treatments that reduce the flares.', array['all']::text[], array['sensitive']::text[], array['redness']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/rosacea/']::text[], false),
  ('1a0234f2-0b00-cd83-d01f-7ae2e2ae7773'::uuid, 'face-all-shade-and-hat-between-eleven-and-four', 'face', 'Σκιά και καπέλο ανάμεσα στις 11 και τις 4', 'Shade and a hat between eleven and four', 'Το αντηλιακό είναι το τελευταίο μέτρο, όχι το πρώτο: τις ώρες που η σκιά σου είναι πιο κοντή από εσένα, η σκιά, ένα καπέλο με γείσο και γυαλιά ηλίου κόβουν περισσότερη ακτινοβολία από οποιαδήποτε κρέμα. Η ελληνική παράδοση του μεσημεριανού ύπνου έχει και δερματολογική λογική. Η άμμος και η θάλασσα αντανακλούν, οπότε η ομπρέλα στην παραλία δεν αρκεί από μόνη της.', 'Sunscreen is the last line of defence, not the first: in the hours when your shadow is shorter than you, shade, a brimmed hat and sunglasses cut more radiation than any cream. The Greek tradition of the midday rest has a dermatological logic too. Sand and sea reflect, so the beach umbrella alone is not enough.', array['all']::text[], array['all']::text[], array['sun']::text[], array['eu','global']::text[], array['https://www.nhs.uk/live-well/seasonal-health/sunscreen-and-sun-safety/']::text[], false),
  ('90d91b19-40ef-19c9-cee8-db377c621b75'::uuid, 'face-all-sheet-mask-do-not-let-it-dry', 'face', 'Υφασμάτινη μάσκα: βγάλ’ την πριν στεγνώσει', 'Sheet mask: take it off before it dries', 'Όσο η μάσκα είναι υγρή δίνει νερό στο δέρμα· όταν αρχίζει να στεγνώνει, το χαρτί τραβά το νερό πίσω. Δεκαπέντε με είκοσι λεπτά αρκούν, και το υπόλοιπο έκχυμα του φακέλου πάει στον λαιμό και τα χέρια. Μετά, ενυδατική για να σφραγίσει — αλλιώς η λάμψη κρατά μία ώρα.', 'While the mask is wet it gives water to the skin; once it starts to dry, the sheet pulls the water back out. Fifteen to twenty minutes is enough, and the leftover essence in the pouch goes on neck and hands. Then moisturise to seal — otherwise the glow lasts an hour.', array['all']::text[], array['all']::text[], array['hydration']::text[], array['kr']::text[], '{}'::text[], true),
  ('21e960dc-6f93-9101-c946-75dd6d3237f6'::uuid, 'face-all-signs-of-a-damaged-barrier', 'face', 'Πότε ο φραγμός του δέρματος «φωνάζει» για βοήθεια', 'When the skin barrier is crying out for help', 'Τσούξιμο με απλό νερό ή ενυδατική, ξεφλούδισμα μαζί με γυαλάδα, κοκκινίλα που δεν φεύγει και προϊόντα που ξαφνικά «δεν ταιριάζουν» είναι σημάδια φραγμού που έχει ξεπεράσει τα όριά του. Σταμάτα κάθε οξύ, ρετινόλη και scrub για δύο εβδομάδες και μείνε σε ήπιο καθαριστικό, κρέμα με κεραμίδια και αντηλιακό. Αν δεν ηρεμήσει σε δύο εβδομάδες, δες δερματολόγο — μπορεί να μην είναι απλός ερεθισμός.', 'Stinging from plain water or moisturiser, flaking alongside shine, redness that will not fade and products that suddenly “don’t agree” are the signs of a barrier pushed past its limit. Stop every acid, retinol and scrub for two weeks and stick to a gentle cleanser, a ceramide cream and sunscreen. If it has not calmed in two weeks, see a dermatologist — it may not be simple irritation.', array['all']::text[], array['all']::text[], array['redness','hydration']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin']::text[], false),
  ('98bfbf17-9858-0f3a-a692-d5e8a45d48d1'::uuid, 'face-all-sleep-shows-on-the-skin', 'face', 'Ο ύπνος φαίνεται στο δέρμα πριν φανεί οπουδήποτε αλλού', 'Sleep shows on the skin before it shows anywhere else', 'Λίγες νύχτες με πέντε ώρες ύπνου φτάνουν για θαμπή όψη, πρησμένα μάτια και πιο αργή επούλωση των σπυριών· η επιδερμίδα επισκευάζεται κυρίως τη νύχτα. Καμία κρέμα δεν αντικαθιστά τις επτά ώρες. Κοιμήσου ανάσκελα αν μπορείς — το πλάγιο μαξιλάρι χαράζει με τον καιρό γραμμές στο μάγουλο.', 'A few nights of five hours’ sleep are enough for a dull look, puffy eyes and slower healing of spots; the skin repairs itself mostly at night. No cream replaces seven hours. Sleep on your back if you can — a pillow pressed to the side etches cheek lines over time.', array['all']::text[], array['all']::text[], array['general','aging']::text[], array['global']::text[], '{}'::text[], true),
  ('81403f87-eed5-32ee-5ced-97bc506d1ad7'::uuid, 'face-all-sunscreen-amount-two-finger-lengths', 'face', 'Ποσότητα αντηλιακού: δύο δάχτυλα για το πρόσωπο', 'Sunscreen amount: two finger-lengths for the face', 'Οι περισσότεροι βάζουν το ένα τέταρτο ως το μισό της ποσότητας με την οποία μετρήθηκε ο δείκτης, οπότε το SPF 50 γίνεται στην πράξη 10–15. Για πρόσωπο και λαιμό χρειάζεσαι γραμμή αντηλιακού σε μήκος δύο δαχτύλων, ή περίπου μισό κουταλάκι του γλυκού. Για όλο το σώμα στην παραλία, περίπου έξι-οκτώ κουταλάκια.', 'Most people apply a quarter to half of the amount the SPF was tested with, so SPF 50 becomes 10–15 in practice. For face and neck you need a line of sunscreen two finger-lengths long, or about half a teaspoon. For the whole body at the beach, roughly six to eight teaspoons.', array['all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.nhs.uk/live-well/seasonal-health/sunscreen-and-sun-safety/']::text[], false),
  ('aa0d876e-54fe-a87f-9f55-39d13af68bc3'::uuid, 'face-all-sunscreen-every-day-clouds-included', 'face', 'Αντηλιακό κάθε μέρα — και με συννεφιά', 'Sunscreen every day — clouds included', 'Έως και το 80 % της υπεριώδους ακτινοβολίας περνά μέσα από τα σύννεφα, και η UVA, που γερνά το δέρμα, περνά και από τα τζάμια του αυτοκινήτου και του γραφείου. Το αντηλιακό είναι το μόνο «αντιγηραντικό» με αδιαμφισβήτητα στοιχεία. Κάνε το το τελευταίο βήμα της πρωινής ρουτίνας, όπως το βούρτσισμα των δοντιών.', 'Up to 80 % of UV radiation passes through clouds, and UVA — the ageing kind — comes through car and office windows too. Sunscreen is the only “anti-ageing” product with undisputed evidence. Make it the last step of your morning routine, like brushing your teeth.', array['all']::text[], array['all']::text[], array['sun','aging']::text[], array['global']::text[], array['https://www.who.int/news-room/questions-and-answers/item/radiation-sun-protection']::text[], false),
  ('5dfdc135-be39-b0e1-5659-e041e74e0bcf'::uuid, 'face-all-us-sunscreen-is-an-otc-drug', 'face', 'Γιατί τα αμερικανικά αντηλιακά διαφέρουν από τα ευρωπαϊκά', 'Why US sunscreens differ from European ones', 'Στις ΗΠΑ το αντηλιακό ρυθμίζεται ως φάρμακο χωρίς συνταγή από τον FDA, και τα νεότερα φίλτρα της Ευρώπης και της Ασίας (Tinosorb, Mexoryl, Uvinul A Plus) δεν έχουν εγκριθεί εκεί. Γι’ αυτό τα αμερικανικά συχνά βασίζονται σε ορυκτά φίλτρα ή σε παλαιότερα οργανικά και έχουν λιγότερο κομψές υφές. Στην Ελλάδα έχεις πρόσβαση και στις δύο αγορές — εκμεταλλεύσου τα ευρωπαϊκά φίλτρα.', 'In the US sunscreen is regulated as an over-the-counter drug by the FDA, and the newer filters of Europe and Asia (Tinosorb, Mexoryl, Uvinul A Plus) are not approved there. That is why US sunscreens often rely on mineral or older organic filters and have less elegant textures. In Greece you have access to both markets — make use of the European filters.', array['all']::text[], array['all']::text[], array['sun']::text[], array['us','eu']::text[], array['https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun']::text[], false),
  ('24fdd63f-1155-e9e2-7304-10faf77fd8c6'::uuid, 'face-all-vitamin-c-that-turned-orange-is-done', 'face', 'Βιταμίνη C που έγινε πορτοκαλί: πέταξέ την', 'Vitamin C that turned orange: throw it out', 'Το L-ασκορβικό οξύ οξειδώνεται με το φως, τη ζέστη και τον αέρα· ο ορός από σχεδόν διάφανος γίνεται κίτρινος, μετά πορτοκαλί-καφέ. Στο στάδιο αυτό δεν προσφέρει αντιοξειδωτική προστασία και μπορεί να λεκιάσει. Αγόραζε μικρές συσκευασίες σε αδιαφανές μπουκάλι, φύλαξέ το στο ψυγείο και τελείωσέ το μέσα σε τρεις μήνες.', 'L-ascorbic acid oxidises with light, heat and air; the serum goes from nearly clear to yellow, then orange-brown. At that stage it offers no antioxidant protection and may stain. Buy small opaque bottles, keep it in the fridge and finish it within three months.', array['all']::text[], array['all']::text[], array['pigmentation','aging']::text[], array['global']::text[], '{}'::text[], true),
  ('f062a725-454b-290d-2be4-d8b1d2f7d3e4'::uuid, 'face-all-when-to-see-a-dermatologist', 'face', 'Πότε σταματάς τα προϊόντα και πας σε δερματολόγο', 'When to stop the products and see a dermatologist', 'Ακμή που αφήνει ουλές ή επιμένει πάνω από τρεις μήνες, κοκκινίλα ή ξεφλούδισμα που δεν υποχωρεί σε δύο εβδομάδες ανάπαυσης, ελιά που αλλάζει, πληγή που δεν κλείνει σε τρεις εβδομάδες, ξαφνικές κηλίδες ή φαγούρα που σε ξυπνά — όλα αυτά δεν λύνονται με έναν ακόμη ορό. Ο δερματολόγος βλέπει σε δέκα λεπτά αυτό που το διαδίκτυο δεν θα βρει ποτέ. Οι συμβουλές εδώ είναι γενική ενημέρωση, όχι διάγνωση.', 'Acne that scars or lasts over three months, redness or flaking that does not settle after two weeks of rest, a changing mole, a sore that has not healed in three weeks, sudden patches or itching that wakes you — none of these is solved by one more serum. A dermatologist sees in ten minutes what the internet never will. The tips here are general information, not a diagnosis.', array['all']::text[], array['all']::text[], array['general','acne','redness','sun']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/acne/','https://www.nhs.uk/conditions/melanoma-skin-cancer/']::text[], false),
  ('c7c782e6-09de-2714-5059-9bcd657b6577'::uuid, 'face-all-winter-heating-dryness', 'face', 'Χειμώνας με θέρμανση: το δέρμα χάνει νερό στον αέρα', 'Winter with the heating on: the skin loses water to the air', 'Τα καλοριφέρ και το κλιματιστικό ρίχνουν την υγρασία του δωματίου κάτω από 30 %, και το δέρμα παραδίδει νερό στον ξηρό αέρα όλη νύχτα. Πρόσθεσε κρέμα με κεραμίδια πάνω από τον ορό, βάλε έναν υγραντήρα ή ένα δοχείο νερό στο καλοριφέρ του υπνοδωματίου και χαμήλωσε τη θερμοκρασία του ντους. Τα χείλη και τα χέρια το νιώθουν πρώτα.', 'Radiators and air conditioning push room humidity below 30 %, and the skin hands water to the dry air all night. Add a ceramide cream over your serum, run a humidifier or set a bowl of water on the bedroom radiator and turn the shower temperature down. Lips and hands feel it first.', array['all']::text[], array['dry','sensitive','all']::text[], array['hydration']::text[], array['eu','global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin']::text[], false),
  ('a387832f-61b3-da14-e0d3-d96cc616230c'::uuid, 'face-men-beard-oil-is-for-the-skin-underneath', 'face', 'Το λάδι γενειάδας είναι για το δέρμα, όχι μόνο για την τρίχα', 'Beard oil is for the skin, not just the hair', 'Η φαγούρα των πρώτων εβδομάδων μιας γενειάδας έρχεται από το δέρμα που δεν φτάνει να ενυδατωθεί κάτω από την τρίχα. Λίγες σταγόνες ελαφριού ελαίου, δουλεμένες με τα δάχτυλα μέχρι το δέρμα, μαλακώνουν και την τρίχα και τον ερεθισμό. Σε ελαφρώς νωπή γενειάδα απλώνεται ευκολότερα και χρειάζεται λιγότερο.', 'The itch of a beard’s first weeks comes from skin that no longer gets moisturised under the hair. A few drops of a light oil, worked down to the skin with your fingers, soften both the hair and the irritation. On a slightly damp beard it spreads more easily and you need less.', array['men']::text[], array['all']::text[], array['beard','hydration']::text[], array['global']::text[], '{}'::text[], true),
  ('c9d3bc4a-3869-a325-4e0b-3f790689e709'::uuid, 'face-men-beardruff-may-be-seborrhoeic-dermatitis', 'face', '«Πιτυρίδα» στη γενειάδα που επιμένει: ρώτα δερματολόγο', 'Persistent “beardruff”: ask a dermatologist', 'Λίγο ξεφλούδισμα διορθώνεται με ενυδάτωση, αλλά κίτρινες λιπαρές φολίδες με κοκκινίλα στη γενειάδα, τα φρύδια ή δίπλα στη μύτη είναι συχνά σμηγματορροϊκή δερματίτιδα. Δεν φεύγει με λάδια· χρειάζεται αντιμυκητιασικό σαμπουάν ή κρέμα που θα προτείνει γιατρός. Είναι συνηθισμένη, δεν είναι θέμα καθαριότητας και ελέγχεται εύκολα όταν διαγνωστεί.', 'A little flaking is fixed by moisturising, but greasy yellow flakes with redness in the beard, eyebrows or beside the nose are often seborrhoeic dermatitis. Oils will not clear it; it needs an antifungal shampoo or cream a doctor can suggest. It is common, not a hygiene issue, and easy to control once diagnosed.', array['men']::text[], array['all']::text[], array['beard','redness']::text[], array['global']::text[], array['https://www.mayoclinic.org/diseases-conditions/seborrheic-dermatitis/symptoms-causes/syc-20352710']::text[], false),
  ('6a345f3c-dc7a-a49e-091c-f0765903e284'::uuid, 'face-men-change-the-blade-often', 'face', 'Άλλαζε λεπίδα πριν αρχίσει να «τραβάει»', 'Change the blade before it starts to drag', 'Μια στομωμένη λεπίδα δεν κόβει την τρίχα, την τραβά — και μαζί της ξύνει το δέρμα. Πέντε ως οκτώ ξυρίσματα είναι το όριο για τις περισσότερες λεπίδες, λιγότερα αν η γενειάδα είναι σκληρή. Ξέπλενε το ξυράφι καλά και άφησέ το να στεγνώσει έξω από την ντουζιέρα, για να μη σκουριάσει και μαζέψει βακτήρια.', 'A dull blade does not cut the hair, it pulls it — and scrapes the skin along the way. Five to eight shaves is the limit for most blades, fewer with coarse stubble. Rinse the razor well and let it dry outside the shower so it does not rust or collect bacteria.', array['men']::text[], array['all']::text[], array['shaving','redness']::text[], array['global']::text[], '{}'::text[], true),
  ('002d1926-6da9-d89e-037a-d7fd8c7990c3'::uuid, 'face-men-ingrown-hairs-do-not-pluck', 'face', 'Τρίχες που μεγαλώνουν προς τα μέσα: μην τις ξεριζώνεις', 'Ingrown hairs: do not pluck them out', 'Οι τρίχες που γυρίζουν μέσα στο δέρμα βγάζουν σπυράκια που μοιάζουν με ακμή, συχνά στον λαιμό. Το ξερίζωμα και το ζούληγμα αφήνουν σημάδια και μπορεί να μολύνουν· άφησε την περιοχή αξύριστη για λίγες μέρες, κάνε ζεστές κομπρέσες και χρησιμοποίησε ήπιο απολεπιστικό με σαλικυλικό οξύ. Αν γίνονται συχνά, μια ηλεκτρική ξυριστική που δεν κόβει τόσο κοντά βοηθά περισσότερο από οποιαδήποτε κρέμα.', 'Hairs that curl back into the skin raise acne-like bumps, often on the neck. Plucking and squeezing leave marks and can infect; leave the area unshaved for a few days, use warm compresses and a gentle salicylic acid exfoliant. If they keep coming back, an electric shaver that does not cut as close helps more than any cream.', array['men']::text[], array['all']::text[], array['shaving','acne']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/ingrown-hairs/']::text[], false),
  ('fa4dc229-3404-f20a-2bb0-7cace3b2214a'::uuid, 'face-men-razor-burn-cold-rinse-and-balm', 'face', 'Κάψιμο από το ξύρισμα: κρύο νερό και βάλσαμο, όχι κολόνια', 'Razor burn: cold water and a balm, not a splash', 'Το κάψιμο μετά το ξύρισμα είναι ερεθισμός του φραγμού, όχι «μικρόβια», οπότε το οινόπνευμα των παλιών κολονιών το χειροτερεύει. Ξέπλυνε με κρύο νερό, ταμπόναρε και βάλε ένα βάλσαμο χωρίς οινόπνευμα με αλλαντοΐνη ή πανθενόλη. Αν κοκκινίζεις κάθε φορά, δοκίμασε ξύρισμα κάθε δεύτερη μέρα για δύο εβδομάδες.', 'Razor burn is barrier irritation, not “germs”, so the alcohol in old-style splashes makes it worse. Rinse with cold water, pat dry and apply an alcohol-free balm with allantoin or panthenol. If you redden every time, try shaving every other day for two weeks.', array['men']::text[], array['sensitive','all']::text[], array['shaving','redness']::text[], array['global']::text[], '{}'::text[], true),
  ('2a12447a-6eb8-abda-d73f-1b1b5fe8b805'::uuid, 'face-men-rinse-after-the-gym', 'face', 'Μετά το γυμναστήριο: ξέπλυμα μέσα σε μισή ώρα', 'After the gym: rinse within half an hour', 'Ιδρώτας, σμήγμα και η τριβή από πετσέτες ή κράνη φράζουν πόρους και φέρνουν σπυράκια στο μέτωπο, την πλάτη και τη γραμμή των μαλλιών. Ξέπλυνε το πρόσωπο με νερό ή ένα ήπιο καθαριστικό μέσα σε 20–30 λεπτά από την προπόνηση και άλλαξε την ιδρωμένη μπλούζα. Μη σκουπίζεις το πρόσωπο με την πετσέτα του γυμναστηρίου — ταμπόναρε με καθαρή.', 'Sweat, sebum and friction from towels or helmets clog pores and raise spots on the forehead, back and hairline. Rinse your face with water or a gentle cleanser within 20–30 minutes of training and change the sweaty shirt. Do not wipe your face with the gym towel — pat with a clean one.', array['men','all']::text[], array['oily','combination','all']::text[], array['acne','general']::text[], array['global']::text[], '{}'::text[], true),
  ('486a6b51-0229-1576-45c5-c31e90276fc1'::uuid, 'face-men-shave-after-shower-with-the-grain', 'face', 'Ξύρισμα μετά το ντους, με τη φορά της τρίχας', 'Shave after the shower, with the grain', 'Το ζεστό νερό μαλακώνει την τρίχα και ανοίγει το δρόμο στη λεπίδα, γι’ αυτό το ξύρισμα μετά το ντους ερεθίζει λιγότερο. Πέρνα το ξυράφι με τη φορά που φυτρώνει η τρίχα, χωρίς να πιέζεις. Το αντίθετο ξύρισμα δίνει πιο «καθαρό» αποτέλεσμα για λίγες ώρες, αλλά πληρώνεται με κοκκινίλα και τρίχες που μεγαλώνουν προς τα μέσα.', 'Warm water softens the hair and clears the way for the blade, which is why shaving after the shower irritates less. Pass the razor in the direction the hair grows, without pressing. Shaving against the grain gives a “closer” result for a few hours, paid for with redness and ingrown hairs.', array['men']::text[], array['all']::text[], array['shaving','redness']::text[], array['global']::text[], '{}'::text[], true),
  ('36b281df-c564-3f87-f108-9dfe3b482ef3'::uuid, 'face-men-sunscreen-is-not-a-womens-product', 'face', 'Το αντηλιακό δεν είναι «γυναικείο προϊόν»', 'Sunscreen is not a “women’s product”', 'Οι άντρες στην Ελλάδα περνούν περισσότερες ώρες στον ήλιο για δουλειά και άθληση και χρησιμοποιούν αντηλιακό πολύ λιγότερο, γι’ αυτό και οι καρκίνοι του δέρματος εμφανίζονται συχνότερα σε αυτούς. Ένα ελαφρύ gel αντηλιακό δεν γυαλίζει, δεν μυρίζει και μπαίνει σε 30 δευτερόλεπτα το πρωί. Αυτιά, μύτη, σβέρκος και το κεφάλι αν αραιώνουν τα μαλλιά — αυτά καίγονται πρώτα.', 'Men spend more hours in the sun for work and sport and use sunscreen far less, which is one reason skin cancers show up more often in men. A light gel sunscreen does not shine or smell and goes on in 30 seconds in the morning. Ears, nose, neck and the scalp if the hair is thinning — those burn first.', array['men']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.cdc.gov/skin-cancer/sun-safety/index.html']::text[], false),
  ('eb19d51c-1bce-fb1a-d984-0000e7ee19f5'::uuid, 'face-men-wash-the-beard-not-every-day', 'face', 'Πλύνε τη γενειάδα δύο-τρεις φορές την εβδομάδα, όχι κάθε μέρα', 'Wash the beard two or three times a week, not daily', 'Η τρίχα της γενειάδας είναι πιο σκληρή από τα μαλλιά και το δέρμα από κάτω ξηραίνεται εύκολα. Καθημερινό πλύσιμο με σαμπουάν μαλλιών αφαιρεί τα λιπίδια και φέρνει φαγούρα και ξεφλούδισμα. Ένα ήπιο καθαριστικό γενειάδας δύο-τρεις φορές την εβδομάδα και ξέβγαλμα με νερό τις υπόλοιπες μέρες είναι αρκετά για τους περισσότερους.', 'Beard hair is coarser than scalp hair and the skin beneath dries out easily. Daily washing with hair shampoo strips the lipids and brings itch and flaking. A mild beard wash two or three times a week and a water rinse on the other days is enough for most men.', array['men']::text[], array['all']::text[], array['beard','hydration']::text[], array['global']::text[], '{}'::text[], true),
  ('5763cbce-4133-abe7-0f83-b8eb5e91547d'::uuid, 'face-women-clean-brushes-and-sponges', 'face', 'Πινέλα και σφουγγαράκια: πλύσιμο κάθε εβδομάδα', 'Brushes and sponges: wash them weekly', 'Ένα σφουγγαράκι μακιγιάζ που μένει υγρό μέσα στη νεσεσέρ είναι ιδανικός χώρος για βακτήρια και μύκητες, που μετά πάνε κατευθείαν στα μάγουλα. Πλύνε πινέλα και σφουγγάρια με σαπούνι ή ήπιο σαμπουάν μία φορά την εβδομάδα και άφησέ τα να στεγνώσουν οριζόντια. Σφουγγαράκι που μυρίζει ή ξεφτίζει πετιέται.', 'A make-up sponge left damp in a bag is a perfect home for bacteria and fungi, which then go straight onto your cheeks. Wash brushes and sponges with soap or a mild shampoo once a week and let them dry flat. A sponge that smells or crumbles gets thrown away.', array['women']::text[], array['all']::text[], array['acne','general']::text[], array['global']::text[], '{}'::text[], true),
  ('fe11931b-1025-76c7-7293-c1b632672c4c'::uuid, 'face-women-double-cleanse-only-when-needed', 'face', 'Διπλός καθαρισμός μόνο όταν χρειάζεται', 'Double cleanse only when it is needed', 'Ο διπλός καθαρισμός —έλαιο ή βάλσαμο και μετά καθαριστικό με νερό— έχει νόημα το βράδυ, όταν φοράς αντηλιακό ανθεκτικό στο νερό ή μακιγιάζ. Το πρωί ή τις μέρες στο σπίτι ένας καθαρισμός αρκεί· ο διπλός κάθε φορά ξηραίνει. Το λάδι μασάρεται σε στεγνό πρόσωπο και γαλακτωματοποιείται με λίγο νερό πριν ξεπλυθεί.', 'Double cleansing — an oil or balm, then a water-based cleanser — makes sense in the evening, when you wear water-resistant sunscreen or make-up. In the morning or on days at home one cleanse is enough; doubling every time dries you out. Massage the oil onto a dry face and emulsify with a little water before rinsing.', array['women','all']::text[], array['all']::text[], array['general','hydration']::text[], array['kr','jp','global']::text[], '{}'::text[], true),
  ('5aa8b24b-8360-d429-e671-336e6749493f'::uuid, 'face-women-hormonal-acne-on-the-jawline', 'face', 'Σπυράκια στο σαγόνι πριν την περίοδο: ορμονικό μοτίβο', 'Spots on the jawline before your period: a hormonal pattern', 'Βαθιά, επώδυνα σπυράκια στο κάτω μέρος του προσώπου που εμφανίζονται λίγες μέρες πριν την περίοδο ακολουθούν τις ορμονικές διακυμάνσεις, όχι την καθαριότητα. Ένα ήπιο ρετινοειδές ή αζελαϊκό οξύ σε συνεχή χρήση βοηθά περισσότερο από τοπικές «θεραπείες» την ώρα της έξαρσης. Αν επαναλαμβάνεται κάθε μήνα ή αφήνει σημάδια, ο δερματολόγος έχει επιλογές που δεν υπάρχουν στο ράφι.', 'Deep, painful spots on the lower face that appear a few days before your period track hormonal swings, not cleanliness. A mild retinoid or azelaic acid used consistently helps more than spot “treatments” at flare time. If it repeats monthly or leaves marks, a dermatologist has options that are not on the shelf.', array['women']::text[], array['oily','combination','all']::text[], array['acne']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/acne/causes/']::text[], false),
  ('777a3454-19e3-5188-6fc1-fe2d1ba6fc96'::uuid, 'face-women-makeup-with-spf-is-not-enough', 'face', 'Το make-up με SPF δεν αντικαθιστά το αντηλιακό', 'Make-up with SPF does not replace sunscreen', 'Για να πάρεις το SPF που γράφει η συσκευασία χρειάζεσαι περίπου 2 mg ανά τετραγωνικό εκατοστό — για το πρόσωπο, ποσότητα όσο δύο δάχτυλα. Κανείς δεν βάζει τόσο foundation. Βάλε κανονικό αντηλιακό από κάτω και θεώρησε το SPF του μακιγιάζ απλώς ένα μπόνους.', 'To get the SPF on the label you need about 2 mg per square centimetre — for the face, roughly two finger-lengths. Nobody applies that much foundation. Put a proper sunscreen on underneath and treat the SPF in your make-up as a bonus only.', array['women']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/sun-protection/sunscreen-patients/sunscreen-faqs']::text[], false),
  ('fc39d48c-d865-1735-3ff1-e8cb8fba8e3d'::uuid, 'face-women-melasma-needs-tinted-sunscreen', 'face', 'Μέλασμα: το αντηλιακό θέλει και οξείδια σιδήρου', 'Melasma: your sunscreen needs iron oxides too', 'Οι καφέ κηλίδες στα μάγουλα και το μέτωπο σκουραίνουν όχι μόνο από την υπεριώδη αλλά και από το ορατό φως — αυτό που περνά από τα τζάμια. Τα συνηθισμένα φίλτρα δεν το κόβουν· τα αντηλιακά με χρώμα (οξείδια σιδήρου) το κόβουν. SPF 50 κάθε μέρα, όλο τον χρόνο, αλλιώς κάθε θεραπεία λεύκανσης πάει χαμένη.', 'The brown patches on cheeks and forehead darken not only from UV but also from visible light — the kind that comes through windows. Ordinary filters do not block it; tinted sunscreens with iron oxides do. SPF 50 every day, all year, or every brightening treatment is wasted.', array['women','all']::text[], array['all']::text[], array['pigmentation','sun']::text[], array['global']::text[], '{}'::text[], true),
  ('43132099-c919-8291-d6d3-9effbf1ba857'::uuid, 'face-women-menopause-skin-gets-drier', 'face', 'Μετά την εμμηνόπαυση το δέρμα θέλει περισσότερα λιπίδια', 'After menopause the skin wants more lipids', 'Η πτώση των οιστρογόνων μειώνει το κολλαγόνο και το σμήγμα, κι έτσι μια επιδερμίδα που ήταν μικτή γίνεται ξαφνικά ξηρή και πιο λεπτή. Άλλαξε το gel σε κρέμα με κεραμίδια, πρόσθεσε ένα ήπιο ρετινοειδές αν δεν το έχεις ήδη και μην κόψεις το αντηλιακό. Έντονη ξηρότητα, φαγούρα ή εξανθήματα αξίζουν μια επίσκεψη στον δερματολόγο.', 'Falling oestrogen reduces collagen and sebum, so skin that used to be combination suddenly turns dry and thinner. Swap the gel for a ceramide cream, add a mild retinoid if you do not already use one and keep the sunscreen. Marked dryness, itching or rashes deserve a visit to a dermatologist.', array['women']::text[], array['dry','all']::text[], array['hydration','aging']::text[], array['global']::text[], '{}'::text[], true),
  ('3b1e77dd-c901-7462-77eb-25008a59e917'::uuid, 'face-women-neck-chest-and-hands-count-too', 'face', 'Λαιμός, ντεκολτέ και χέρια: ό,τι βάζεις στο πρόσωπο, βάλε κι εκεί', 'Neck, chest and hands: whatever goes on the face goes there too', 'Το δέρμα του λαιμού και των χεριών είναι πιο λεπτό και παίρνει τον ίδιο ήλιο με το πρόσωπο, αλλά σπάνια το ίδιο αντηλιακό. Κατέβασε την κρέμα και το αντηλιακό μέχρι το ντεκολτέ και ξανάβαλε στα χέρια μετά από κάθε πλύσιμο. Οι κηλίδες στα χέρια είναι σχεδόν πάντα ήλιος, όχι ηλικία.', 'The skin of the neck and hands is thinner and gets the same sun as the face, but rarely the same sunscreen. Take your cream and sunscreen down to the chest and reapply on the hands after every wash. Spots on the hands are almost always sun, not age.', array['women','all']::text[], array['all']::text[], array['aging','sun','hands']::text[], array['global']::text[], '{}'::text[], true),
  ('861b32be-c7c8-7f27-b0eb-4ef237be41d6'::uuid, 'face-women-pregnancy-safe-actives', 'face', 'Τι μένει στη ρουτίνα της εγκυμοσύνης', 'What stays in a pregnancy routine', 'Αζελαϊκό οξύ, νιασιναμίδη, υαλουρονικό, γλυκολικό και γαλακτικό οξύ σε χαμηλή συγκέντρωση και αντηλιακό με ορυκτά φίλτρα θεωρούνται γενικά κατάλληλα. Το μέλασμα της εγκυμοσύνης («μάσκα») αντιμετωπίζεται πρώτα με σκιά, καπέλο και tinted αντηλιακό. Κάθε αλλαγή στην αγωγή συζητείται με τον γυναικολόγο ή τον δερματολόγο — όχι με το φόρουμ.', 'Azelaic acid, niacinamide, hyaluronic acid, low-strength glycolic and lactic acid and a mineral-filter sunscreen are generally considered suitable. The “mask of pregnancy” (melasma) is handled first with shade, a hat and a tinted sunscreen. Any change in treatment is discussed with your obstetrician or dermatologist — not the forum.', array['women']::text[], array['all']::text[], array['acne','pigmentation','sun']::text[], array['global']::text[], '{}'::text[], true),
  ('9326b37b-5701-1999-d8cc-96e6c7feaa34'::uuid, 'face-women-pregnancy-skip-retinoids', 'face', 'Εγκυμοσύνη και θηλασμός: κανένα ρετινοειδές', 'Pregnancy and breastfeeding: no retinoids', 'Ρετινόλη, ρετινάλη, αδαπαλένη, τρετινοΐνη και ισοτρετινοΐνη αποφεύγονται από τη στιγμή που προσπαθείς για εγκυμοσύνη και όσο θηλάζεις. Το ίδιο ισχύει για υψηλές συγκεντρώσεις σαλικυλικού οξέος σε μεγάλη έκταση και για την υδροκινόνη. Αν ακολουθείς αγωγή για ακμή, ενημέρωσε τον γιατρό σου πριν συλλάβεις.', 'Retinol, retinal, adapalene, tretinoin and isotretinoin are avoided from the moment you try to conceive and for as long as you breastfeed. The same goes for high-strength salicylic acid over large areas and for hydroquinone. If you are on acne treatment, tell your doctor before conceiving.', array['women']::text[], array['all']::text[], array['acne','aging']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/acne/treatment/']::text[], false),
  ('0bb0d34c-1f21-e877-8f2b-73df4a7ce620'::uuid, 'face-women-remove-makeup-every-night', 'face', 'Το μακιγιάζ φεύγει κάθε βράδυ, όσο κουρασμένη κι αν είσαι', 'Make-up comes off every night, however tired you are', 'Μια νύχτα με μακιγιάζ σημαίνει οκτώ ώρες με χρωστικές, σμήγμα και ρύπους πάνω στους πόρους. Κράτα ένα μικυλλιακό νερό ή μαντιλάκια δίπλα στο κρεβάτι για τις «δεν αντέχω» βραδιές — είναι καλύτερα από το τίποτα. Η μάσκαρα που μένει ξεραίνει τις βλεφαρίδες και τις σπάει.', 'A night in make-up means eight hours of pigments, sebum and dirt on your pores. Keep micellar water or wipes by the bed for the “I can’t” nights — better than nothing. Mascara left on dries the lashes and snaps them.', array['women']::text[], array['all']::text[], array['acne','general']::text[], array['global']::text[], '{}'::text[], true),
  ('37d7b4a9-9970-415e-2220-132da17f3bb4'::uuid, 'nails-acetone-dries-the-plate', 'nails', 'Η ασετόν αφαιρεί και το νερό από το νύχι', 'Acetone strips the water from the nail too', 'Η ασετόν διαλύει το βερνίκι σε δευτερόλεπτα, αλλά διαλύει και τα λιπίδια και την υγρασία της πλάκας και του δέρματος γύρω της — γι’ αυτό τα νύχια ασπρίζουν και τα επωνύχια ξεφλουδίζουν μετά. Για απλό βερνίκι προτίμησε αφαιρετικό χωρίς ασετόν· όταν την χρειάζεσαι για gel, βάλε λάδι γύρω από το νύχι πριν και κρέμα χεριών αμέσως μετά. Στις ΗΠΑ ο FDA επιβλέπει τα προϊόντα νυχιών ως καλλυντικά και προειδοποιεί για σωστό αερισμό.', 'Acetone dissolves polish in seconds, but it also dissolves the lipids and moisture of the plate and the surrounding skin — which is why nails go white and cuticles peel afterwards. For plain polish prefer an acetone-free remover; when you need acetone for gel, oil around the nail first and hand cream straight after. In the US the FDA oversees nail products as cosmetics and warns about proper ventilation.', array['all']::text[], array['all']::text[], array['nails','hands']::text[], array['global','us']::text[], array['https://www.fda.gov/cosmetics/cosmetic-products/nail-care-products']::text[], false),
  ('c42554ee-be81-b14d-d907-9f6a7553d454'::uuid, 'nails-brittle-nails-and-diet-myths', 'nails', 'Εύθραυστα νύχια: τι λέει η διατροφή και τι ο μύθος', 'Brittle nails: what diet does and what is myth', 'Τα νύχια σπάνια είναι εύθραυστα από «έλλειψη ασβεστίου»· η συνηθέστερη αιτία είναι το νερό — συνεχές βρέξιμο και στέγνωμα, απορρυπαντικά, ασετόν. Η βιοτίνη βοηθά μόνο όσους έχουν πραγματική έλλειψη, που είναι σπάνια, και τα συμπληρώματά της αλλοιώνουν εργαστηριακές εξετάσεις (θυρεοειδή, καρδιακά ένζυμα). Αν τρως ισορροπημένα, η λύση είναι γάντια, λάδι και υπομονή — όχι χάπι.', 'Nails are rarely brittle from a “calcium deficiency”; the usual cause is water — constant wetting and drying, detergents, acetone. Biotin helps only people with a genuine deficiency, which is rare, and biotin supplements distort lab tests (thyroid, cardiac enzymes). If you eat a balanced diet, the fix is gloves, oil and patience — not a pill.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://ods.od.nih.gov/factsheets/Biotin-HealthProfessional/','https://www.mayoclinic.org/healthy-lifestyle/adult-health/in-depth/nails/art-20044954']::text[], false),
  ('72f6f3b6-bc3a-89cf-bf44-821eb37b7a3c'::uuid, 'nails-do-not-cut-the-cuticles', 'nails', 'Τα επωνύχια δεν κόβονται — σπρώχνονται απαλά', 'Cuticles are not cut — they are pushed back gently', 'Το επωνύχιο σφραγίζει το σημείο όπου γεννιέται το νύχι και κρατά έξω βακτήρια και μύκητες. Όταν το κόβεις, ανοίγεις πόρτα σε λοιμώξεις και το νύχι βγαίνει με ραβδώσεις. Μετά το ντους, όταν είναι μαλακό, σπρώξε το απαλά με πετσέτα ή ξυλάκι και βάλε λάδι επωνυχίων· κόψε μόνο ό,τι έχει ήδη ξεκολλήσει.', 'The cuticle seals the spot where the nail is born and keeps bacteria and fungi out. Cut it and you open a door to infection, and the nail grows out ridged. After the shower, when it is soft, push it back gently with a towel or an orange stick and apply cuticle oil; trim only what has already lifted.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/nail-care-secrets/basics/healthy-nail-tips','https://www.mayoclinic.org/healthy-lifestyle/adult-health/in-depth/nails/art-20044954']::text[], false),
  ('d8f4a4fb-d3ec-406e-e55e-04c1d60d80ce'::uuid, 'nails-file-in-one-direction', 'nails', 'Λιμάρισμα προς μία κατεύθυνση, σε στεγνά νύχια', 'File in one direction, on dry nails', 'Το πέρα-δώθε με τη λίμα ξεφτίζει τις στρώσεις κερατίνης στην άκρη και το νύχι αρχίζει να ξεφλουδίζει. Λιμάρισε από την πλαϊνή άκρη προς το κέντρο, με απαλές κινήσεις προς την ίδια κατεύθυνση, και πάντα σε στεγνό νύχι — το βρεγμένο σκίζεται εύκολα. Μια γυάλινη λίμα είναι πιο ήπια από τη χάρτινη και πλένεται.', 'Sawing back and forth frays the keratin layers at the edge and the nail starts to peel. File from the side edge towards the centre with gentle strokes in one direction, always on a dry nail — a wet one tears easily. A glass file is gentler than an emery board and can be washed.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.mayoclinic.org/healthy-lifestyle/adult-health/in-depth/nails/art-20044954']::text[], false),
  ('cffea30f-4ac1-6dd5-2cb7-aaea267b8d5f'::uuid, 'nails-fungal-signs-see-a-doctor', 'nails', 'Κίτρινο, χοντρό νύχι που θρυμματίζεται: μύκητας — δες γιατρό', 'A yellow, thick, crumbly nail: a fungus — see a doctor', 'Νύχι που κιτρινίζει ή ασπρίζει, παχαίνει, θρυμματίζεται στην άκρη ή σηκώνεται από την κοίτη του είναι συνήθως μυκητίαση — πολύ συχνή στα πόδια, από πισίνες, αθλητικά παπούτσια και ζεστές κάλτσες. Τα βερνίκια του ραφιού σπάνια αρκούν· ο γιατρός επιβεβαιώνει τη διάγνωση και δίνει αγωγή μηνών. Μην καλύπτεις το νύχι με βερνίκι ή gel — κλειδώνεις τον μύκητα μέσα.', 'A nail that turns yellow or white, thickens, crumbles at the tip or lifts from its bed is usually a fungal infection — very common on the feet, from pools, trainers and warm socks. Shelf polishes rarely suffice; a doctor confirms the diagnosis and prescribes a course of months. Do not cover the nail with polish or gel — you lock the fungus in.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/fungal-nail-infection/']::text[], false),
  ('49223043-ed8c-da05-0f9b-3612143beca2'::uuid, 'nails-gel-and-acrylic-take-breaks', 'nails', 'Gel και ακρυλικό: δώσε στο νύχι διαλείμματα', 'Gel and acrylic: give the nail breaks', 'Το πρόβλημα με το ημιμόνιμο δεν είναι το προϊόν αλλά η αφαίρεση: το λιμάρισμα και το ξύσιμο λεπταίνουν την πλάκα κάθε φορά. Μετά από δύο-τρεις εφαρμογές άφησε τα νύχια γυμνά για δύο εβδομάδες με λάδι επωνυχίων κάθε βράδυ. Στο σαλόνι ζήτα αφαίρεση με μούλιασμα, όχι ξύσιμο, και βάλε αντηλιακό στα χέρια πριν τη λάμπα UV.', 'The problem with semi-permanent polish is not the product but the removal: filing and scraping thin the plate every time. After two or three applications leave the nails bare for two weeks with cuticle oil every night. At the salon ask for soak-off removal, not scraping, and put sunscreen on your hands before the UV lamp.', array['women','all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/nail-care-secrets/basics/artificial-nails']::text[], false),
  ('93b23746-aa88-f603-7de8-b5c6df21ddc1'::uuid, 'nails-gloves-for-dishes-and-cleaning', 'nails', 'Γάντια για τα πιάτα και την καθαριότητα', 'Gloves for the dishes and the cleaning', 'Το νύχι φουσκώνει με το νερό και ξαναμαζεύει όταν στεγνώνει· δέκα τέτοιοι κύκλοι τη μέρα, με απορρυπαντικό, είναι η πρώτη αιτία για νύχια που ξεφλουδίζουν και σκίζονται. Ένα ζευγάρι γάντια κουζίνας με βαμβακερή επένδυση κόβει το μεγαλύτερο μέρος της ζημιάς. Μετά το πλύσιμο των χεριών, κρέμα μέχρι τα επωνύχια.', 'The nail swells with water and shrinks again as it dries; ten such cycles a day, with detergent, are the main cause of peeling and splitting nails. A pair of cotton-lined kitchen gloves cuts most of the damage. After washing your hands, cream right up to the cuticles.', array['all']::text[], array['all']::text[], array['nails','hands']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/nail-care-secrets/basics/healthy-nail-tips','https://www.mayoclinic.org/healthy-lifestyle/adult-health/in-depth/nails/art-20044954']::text[], false),
  ('c2c7dcf6-d754-75d2-6251-bd73e314fdcf'::uuid, 'nails-hand-cream-after-every-wash', 'nails', 'Κρέμα χεριών μετά από κάθε πλύσιμο, μέχρι τα επωνύχια', 'Hand cream after every wash, right up to the cuticles', 'Τα χέρια πλένονται δέκα φορές τη μέρα και δεν έχουν σχεδόν καθόλου σμηγματογόνους αδένες στην παλάμη, γι’ αυτό σκάνε πρώτα τον χειμώνα. Ένα μικρό σωληνάριο δίπλα σε κάθε νιπτήρα και στην τσάντα κάνει την κρέμα αντανακλαστικό, όχι αγγαρεία. Το βράδυ μια πιο πλούσια κρέμα με ουρία και, για τις πολύ σκασμένες μέρες, βαμβακερά γάντια από πάνω.', 'Hands are washed ten times a day and have almost no sebaceous glands on the palm, which is why they crack first in winter. A small tube by every sink and in your bag makes cream a reflex, not a chore. At night a richer cream with urea and, on the very cracked days, cotton gloves over it.', array['all']::text[], array['dry','all']::text[], array['hands','nails','hydration']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin']::text[], false),
  ('df739cf5-9b5f-981b-52fb-20e17c948afa'::uuid, 'nails-hangnails-clip-do-not-tear', 'nails', 'Παρανυχίδες: κόψιμο με νυχοκόπτη, όχι τράβηγμα', 'Hangnails: clip them, never tear', 'Η μικρή λωρίδα δέρματος δίπλα στο νύχι τραβιέται πολύ πιο βαθιά απ’ όσο δείχνει, και η πληγή που μένει μολύνεται εύκολα (παρωνυχία). Κόψε την παρανυχίδα στη βάση με καθαρό νυχοκόπτη ή ψαλιδάκι, βάλε λίγο λάδι ή κρέμα και άφησέ την ήσυχη. Ξηρά χέρια βγάζουν περισσότερες — η κρέμα χεριών είναι η πρόληψη. Αν το δάχτυλο κοκκινίσει, πρηστεί ή πονά, δες γιατρό.', 'That little strip of skin beside the nail tears far deeper than it looks, and the wound it leaves gets infected easily (paronychia). Clip the hangnail at the base with a clean clipper or small scissors, apply a little oil or cream and leave it alone. Dry hands grow more of them — hand cream is the prevention. If the finger reddens, swells or hurts, see a doctor.', array['all']::text[], array['all']::text[], array['nails','hands']::text[], array['global']::text[], array['https://www.mayoclinic.org/healthy-lifestyle/adult-health/in-depth/nails/art-20044954']::text[], false),
  ('fb8c1702-f245-e686-41c0-da7fcb45afcf'::uuid, 'nails-how-to-stop-biting', 'nails', 'Για να κόψεις το δάγκωμα των νυχιών', 'To stop biting your nails', 'Το δάγκωμα μεταφέρει μικρόβια από τα χέρια στο στόμα και αντίστροφα, πληγώνει τα επωνύχια και, με τα χρόνια, παραμορφώνει το νύχι. Κράτα τα νύχια πολύ κοντά και λιμαρισμένα ώστε να μην έχει «τι να πιάσεις», βάλε πικρό βερνίκι και σημείωσε πότε το κάνεις — το άγχος και η βαρεμάρα είναι οι συνήθεις στιγμές. Ένα όμορφο μανικιούρ ή ένα stress ball στο γραφείο βοηθούν περισσότερο από τη θέληση.', 'Biting carries germs from hands to mouth and back, wounds the cuticles and, over years, deforms the nail. Keep nails very short and filed so there is nothing to grab, use a bitter polish and note when you do it — stress and boredom are the usual moments. A nice manicure or a stress ball at your desk helps more than willpower.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/nail-care-secrets/basics/stop-biting-nails']::text[], false),
  ('707f8cff-0691-5810-db81-cb3c9c3d3df1'::uuid, 'nails-men-short-clean-and-buffed', 'nails', 'Για άντρες: κοντά, καθαρά και, αν θέλεις, ελαφρά γυαλισμένα', 'For men: short, clean and, if you like, lightly buffed', 'Το αντρικό μανικιούρ είναι τρία πράγματα: νύχια κοντά σε ευθεία γραμμή με στρογγυλεμένες γωνίες, καθαρά από κάτω χωρίς αιχμηρά εργαλεία, και επωνύχια ενυδατωμένα αντί για κομμένα. Ένα πέρασμα με buffer μία φορά τον μήνα δίνει φυσική γυαλάδα που δεν φαίνεται «φτιαγμένη». Ο νυχοκόπτης κόβει ίσια· η λίμα τελειώνει το σχήμα.', 'A men’s manicure is three things: nails short in a straight line with rounded corners, clean underneath without sharp tools, and cuticles moisturised rather than cut. One pass with a buffer once a month gives a natural shine that does not look “done”. The clipper cuts straight; the file finishes the shape.', array['men']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], '{}'::text[], true),
  ('5f18be6a-e3e3-6cae-f877-e38e6b8557af'::uuid, 'nails-ridges-and-white-spots-are-usually-harmless', 'nails', 'Ραβδώσεις και λευκά στίγματα: συνήθως αθώα', 'Ridges and white spots: usually harmless', 'Οι κάθετες ραβδώσεις πληθαίνουν με την ηλικία και είναι φυσιολογικές· τα λευκά στίγματα είναι σχεδόν πάντα μικροτραυματισμοί της βάσης του νυχιού από πριν εβδομάδες — όχι έλλειψη ασβεστίου. Τα σημάδια που θέλουν γιατρό είναι άλλα: οριζόντια αυλάκια σε όλα τα νύχια, σκούρα γραμμή που δεν μεγαλώνει προς τα έξω, νύχια που κυρτώνουν σαν κουτάλι ή σαν ρολόι. Τα νύχια είναι παράθυρο στην υγεία, αλλά τα περισσότερα «σημάδια» είναι απλώς ζωή.', 'Vertical ridges multiply with age and are normal; white spots are almost always small injuries to the nail base from weeks ago — not a calcium deficiency. The signs that need a doctor are different: horizontal grooves across all nails, a dark streak that does not grow out, nails curving like a spoon or a watch glass. Nails are a window on health, but most “signs” are just life.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://medlineplus.gov/naildiseases.html']::text[], false),
  ('c9d83a41-337d-76ec-54e8-f89bd1b2f44c'::uuid, 'nails-salon-ventilation-and-pregnancy', 'nails', 'Στο σαλόνι: αερισμός, ειδικά στην εγκυμοσύνη', 'At the salon: ventilation, especially in pregnancy', 'Ασετόν, μονομερή ακρυλικού και σκόνη λιμαρίσματος μαζεύονται στον αέρα ενός κλειστού σαλονιού, και οι μυρωδιές που «ζαλίζουν» δεν είναι απλώς ενοχλητικές. Στην εγκυμοσύνη δεν υπάρχει λόγος να κόψεις το μανικιούρ, αλλά διάλεξε χώρο με απορρόφηση ή ανοιχτά παράθυρα, ζήτα το απλό βερνίκι αντί για ακρυλικό και μη μένεις όση ώρα λιμάρουν δίπλα σου. Το ίδιο ισχύει για όσους δουλεύουν εκεί καθημερινά.', 'Acetone, acrylic monomers and filing dust build up in the air of a closed salon, and the smells that make you light-headed are not merely annoying. In pregnancy there is no need to give up manicures, but pick a place with extraction or open windows, ask for plain polish instead of acrylic and do not sit through someone else’s filing. The same goes for the people who work there every day.', array['women']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], '{}'::text[], true),
  ('5866c94c-4c35-e151-47e0-4dc3442cadf6'::uuid, 'nails-toenails-cut-straight-across', 'nails', 'Νύχια ποδιών: ίσιο κόψιμο, όχι στρογγυλεμένο', 'Toenails: cut straight across, not rounded', 'Το νύχι του μεγάλου δαχτύλου που κόβεται στρογγυλά ή πολύ κοντά βυθίζεται στο πλαϊνό δέρμα και γίνεται «είσφρυση» — επώδυνη και εύκολα μολυσμένη. Κόψε ίσια, στο ύψος της άκρης του δαχτύλου, και λιμάρισε μόνο τις γωνίες ελαφρά. Στενά παπούτσια και ιδρωμένες κάλτσες χειροτερεύουν τα πράγματα· ένα νύχι που κοκκινίζει και πονά χρειάζεται γιατρό, όχι «χειρουργείο» στο μπάνιο.', 'A big toenail cut rounded or too short digs into the skin beside it and becomes ingrown — painful and easily infected. Cut straight across at the level of the toe tip and file only the corners lightly. Tight shoes and sweaty socks make it worse; a nail that reddens and hurts needs a doctor, not bathroom surgery.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/ingrown-toenail/']::text[], false)
